import * as fs from 'node:fs'
import * as path from 'node:path'

import {
  getTmuxAvailability,
  quoteForSh,
  type TmuxSplitFlag,
} from './launchers/tmux-launcher.js'
import {createPaneLauncher, type PaneBackend, type PaneSplitDirection} from './pane-launcher.js'
import {applyTmuxLaunchEnv, isWindowsPlatform, shouldUseShell} from './runtime/platform-adapter.js'
import {cleanupSentinelIpc, createSentinelIpcPaths} from './runtime/sentinel-ipc.js'
import {execFileAsync, findExecutable} from './runtime/subprocess-utils.js'
import {preflightWindowsTmux, type WindowsTmuxPreflight} from './runtime/tmux-preflight.js'
import {toMsysPosixPath} from './tmux-primitives.js'

/**
 * Resolve a tool path from bash's perspective.
 * Used on Windows where the tmux backend runs commands in bash,
 * but findExecutable() returns Windows paths (.cmd/.exe) that bash can't execute.
 */
async function resolveToolForBash(toolName: string): Promise<null | string> {
  const bash = findExecutable('bash')
  if (!bash) return null
  const result = await execFileAsync(bash, ['-lc', `command -v ${toolName}`], {
    timeout: 3000,
    env: {...process.env, MSYS_NO_PATHCONV: '1'},
  })
  return result.exitCode === 0 ? result.stdout.trim() || null : null
}

export type DriverMode = 'exec' | 'repl'
export type TmuxSplitOption = 'auto' | TmuxSplitFlag

export interface DriverPreflightResult {
  available: boolean
  error?: string
}

export type DriverPreflight =
  (toolPath: string) => DriverPreflightResult | Promise<DriverPreflightResult>

export interface LaunchDriverOptions {
  allowExecFallback?: boolean | undefined
  args?: string[] | undefined
  autoClose?: boolean | undefined
  cwd?: string | undefined
  env?: Record<string, string> | undefined
  holdMessage?: string | undefined
  holdPane?: boolean | undefined
  mode?: DriverMode | undefined
  preflight?: DriverPreflight | undefined
  promptPath?: string | undefined
  splitFlag?: TmuxSplitOption | undefined
  splitTarget?: string | undefined
  timeoutMs?: number | undefined
  toolBin?: string | undefined
  toolName: string
}

export interface LaunchDriverResult {
  backend: PaneBackend
  exitCode?: number | undefined
  launched: boolean
  mode: DriverMode
  paneId?: string | undefined
  reason?: string | undefined
  sentinelPath?: string | undefined
  stderr?: string | undefined
  stdout?: string | undefined
  toolPath?: string | undefined
  usedTmux: boolean
}

function buildEnvPrefix(env: Record<string, string>): string {
  return Object.entries(env)
    .map(([key, value]) => `${key}=${quoteForSh(value)}`)
    .join(' ')
}

function quoteForPowerShell(input: string): string {
  return `'${input.replaceAll("'", "''")}'`
}

function buildCommandArgs(
  args: string[],
  mode: DriverMode,
  promptPath?: string,
): string[] {
  if (mode !== 'repl' || !promptPath) return args

  if (isWindowsPlatform()) {
    const absolutePromptPath = path.resolve(promptPath)
    const bootstrap = `Read startup instructions from this file path before taking action: ${absolutePromptPath}. Use that file as the initial context.`
    return [...args, bootstrap]
  }

  const promptText = fs.readFileSync(promptPath, 'utf8')
  return [...args, promptText]
}

function buildShToolCommand(
  toolPath: string,
  args: string[],
  env: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  const envPrefix = buildEnvPrefix(env)
  const commandArgs = buildCommandArgs(args, mode, promptPath)
  const argPart = commandArgs.map((arg) => quoteForSh(arg)).join(' ')
  const base = [envPrefix, quoteForSh(toolPath), argPart]
    .filter(Boolean)
    .join(' ')

  if (mode === 'exec' && promptPath) {
    return `${base} < ${quoteForSh(promptPath)}`
  }

  return base
}

function buildPowerShellToolCommand(
  toolPath: string,
  args: string[],
  env: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  const envPrefix = Object.entries(env)
    .map(([key, value]) => `$env:${key}=${quoteForPowerShell(value)}`)
    .join('; ')

  const commandArgs = buildCommandArgs(args, mode, promptPath)
  const argArray = commandArgs.map((arg) => quoteForPowerShell(arg)).join(', ')
  const invocation = `& ${quoteForPowerShell(toolPath)}${argArray ? ` @(${argArray})` : ''}`

  const body = mode === 'exec' && promptPath
    ? `Get-Content -Raw -Path ${quoteForPowerShell(promptPath)} | ${invocation}`
    : invocation

  return [envPrefix, body].filter(Boolean).join('; ')
}

function wrapPaneCommand(
  backend: PaneBackend,
  command: string,
  sentinelPath: string,
  autoClose: boolean,
  holdPane: boolean,
  holdMessage: string,
): string {
  if (backend === 'tmux') {
    // On Windows, convert sentinel path to POSIX for bash redirections.
    // MSYS2 bash maps /c/Users/.../file to C:\Users\...\file on disk,
    // so Node.js reads the same physical file via its original Windows path.
    const safePath = isWindowsPlatform()
      ? toMsysPosixPath(sentinelPath) : sentinelPath
    const base = `${command}; code=$?; printf '%s' "$code" > ${quoteForSh(safePath)}`

    if (autoClose) {
      return `${base}; tmux kill-pane -t "$TMUX_PANE" >/dev/null 2>&1 || true; exit $code`
    }

    if (holdPane) {
      return `${base}; echo; echo ${quoteForSh(holdMessage)}; exec bash`
    }

    return `${base}; exit $code`
  }

  const base = `${command}; $code = $LASTEXITCODE; Set-Content -Path ${quoteForPowerShell(sentinelPath)} -Value $code -NoNewline`

  if (holdPane && !autoClose) {
    return `${base}; Write-Host ''; Write-Host ${quoteForPowerShell(holdMessage)}; Read-Host -Prompt 'Press Enter to close' | Out-Null`
  }

  return `${base}; exit $code`
}

function mapSplitDirection(splitFlag: TmuxSplitOption | undefined): PaneSplitDirection {
  if (splitFlag === 'auto') return 'auto'
  if (splitFlag === '-v') return 'v'
  return 'h'
}

export function isTruthy(value: string | undefined): boolean {
  if (!value) return false
  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

export function resolveToolPath(toolName: string, toolBin?: string): null | string {
  const bin = toolBin?.trim() || toolName
  return findExecutable(bin)
}

export function buildTmuxLaunchEnv(
  envVars: Record<string, string>,
  platform: NodeJS.Platform = process.platform,
): Record<string, string> {
  return applyTmuxLaunchEnv(envVars, platform)
}

export function getWindowsTmuxPreflightFailureReason(
  backend: PaneBackend,
  platform: NodeJS.Platform = process.platform,
  preflight: () => WindowsTmuxPreflight = preflightWindowsTmux,
): null | string {
  if (backend !== 'tmux' || !isWindowsPlatform(platform)) return null
  const result = preflight()
  if (result.available) return null
  return result.reason ?? 'Windows tmux preflight failed'
}

export function withWindowsTmuxWinpty(
  command: string,
  backend: PaneBackend,
  platform: NodeJS.Platform = process.platform,
): string {
  if (backend !== 'tmux' || !isWindowsPlatform(platform)) return command
  return `winpty bash -lc ${quoteForSh(command)}`
}

function buildCommandForBackend(
  backend: PaneBackend,
  toolPath: string,
  args: string[],
  envVars: Record<string, string>,
  mode: DriverMode,
  promptPath?: string,
): string {
  if (backend === 'tmux') {
    return buildShToolCommand(toolPath, args, envVars, mode, promptPath)
  }

  return buildPowerShellToolCommand(toolPath, args, envVars, mode, promptPath)
}

export async function launchDriverInTmuxOrFallback(
  options: LaunchDriverOptions,
): Promise<LaunchDriverResult> {
  const mode = options.mode ?? 'exec'
  const args = options.args ?? []
  const envVars = options.env ?? {}
  const timeoutMs = options.timeoutMs ?? 0
  const toolPath = resolveToolPath(options.toolName, options.toolBin)

  if (!toolPath) {
    return {
      launched: false,
      usedTmux: false,
      backend: 'exec',
      mode,
      reason: `${options.toolBin ?? options.toolName} not found on PATH`,
    }
  }

  if (options.preflight) {
    const preflight = await options.preflight(toolPath)
    if (!preflight.available) {
      return {
        launched: false,
        usedTmux: false,
        backend: 'exec',
        mode,
        toolPath,
        reason: preflight.error ?? 'driver preflight failed',
      }
    }
  }

  if (options.promptPath && !fs.existsSync(options.promptPath)) {
    return {
      launched: false,
      usedTmux: false,
      backend: 'exec',
      mode,
      toolPath,
      reason: `prompt file not found: ${options.promptPath}`,
    }
  }

  const paneLauncher = await createPaneLauncher({requireTmuxSession: true})
  if (paneLauncher) {
    const windowsTmuxPreflightError = getWindowsTmuxPreflightFailureReason(paneLauncher.backend)
    if (windowsTmuxPreflightError) {
      return {
        launched: false,
        usedTmux: false,
        backend: paneLauncher.backend,
        mode,
        toolPath,
        reason: windowsTmuxPreflightError,
      }
    }

    // On Windows with tmux backend, resolve tool path from bash's perspective.
    // findExecutable() returns Windows paths (.cmd/.exe) that bash can't execute.
    let effectiveToolPath = toolPath
    if (isWindowsPlatform() && paneLauncher.backend === 'tmux') {
      const bashPath = await resolveToolForBash(options.toolName)
      if (bashPath) {
        effectiveToolPath = bashPath
      } else {
        return {
          launched: false,
          usedTmux: false,
          backend: paneLauncher.backend,
          mode,
          toolPath,
          reason: `${options.toolName} not found in bash PATH (required for tmux pane)`,
        }
      }
    }

    const sentinel = createSentinelIpcPaths(`aiwcli-pane-${options.toolName}`)

    // Tmux does not always propagate COLORTERM into panes.
    // On winpty, avoid advertising truecolor because it causes palette corruption.
    const effectiveEnvVars = paneLauncher.backend === 'tmux'
      ? buildTmuxLaunchEnv(envVars)
      : envVars

    try {
      const baseCommand = buildCommandForBackend(
        paneLauncher.backend,
        effectiveToolPath,
        args,
        effectiveEnvVars,
        mode,
        options.promptPath,
      )
      const effectiveBaseCommand = withWindowsTmuxWinpty(baseCommand, paneLauncher.backend)

      const holdMessage = options.holdMessage ?? '[aiwcli] Driver exited. Pane held open.'
      const paneCommand = wrapPaneCommand(
        paneLauncher.backend,
        effectiveBaseCommand,
        sentinel.sentinelPath,
        Boolean(options.autoClose),
        Boolean(options.holdPane) && !options.autoClose,
        holdMessage,
      )

      const paneResult = await paneLauncher.launch({
        command: paneCommand,
        splitDirection: mapSplitDirection(options.splitFlag),
        splitTarget: options.splitTarget,
        cwd: options.cwd,
      })

      if (!paneResult.launched) {
        cleanupSentinelIpc(sentinel)
        return {
          launched: false,
          usedTmux: paneLauncher.backend === 'tmux',
          backend: paneLauncher.backend,
          mode,
          toolPath,
          reason: paneResult.reason ?? 'pane launch failed',
          stderr: paneResult.stderr,
        }
      }

      return {
        launched: true,
        usedTmux: paneLauncher.backend === 'tmux',
        backend: paneLauncher.backend,
        mode,
        toolPath,
        paneId: paneResult.paneId,
        sentinelPath: sentinel.sentinelPath,
      }
    } catch (error) {
      cleanupSentinelIpc(sentinel)
      return {
        launched: false,
        usedTmux: paneLauncher.backend === 'tmux',
        backend: paneLauncher.backend,
        mode,
        toolPath,
        reason: `pane launch failed: ${String(error)}`,
      }
    }
  }

  if (options.allowExecFallback) {
    const commandArgs = buildCommandArgs(args, mode, options.promptPath)
    const input = mode === 'exec' && options.promptPath
      ? fs.readFileSync(options.promptPath, 'utf8')
      : undefined

    const result = await execFileAsync(toolPath, commandArgs, {
      input,
      timeout: timeoutMs,
      env: {...process.env, ...envVars},
      shell: shouldUseShell(),
    })

    return {
      launched: true,
      usedTmux: false,
      backend: 'exec',
      mode,
      toolPath,
      exitCode: result.exitCode,
      stdout: result.stdout,
      stderr: result.stderr,
      reason: result.exitCode === 0 ? undefined : `fallback exec exited ${result.exitCode}`,
    }
  }

  const tmux = getTmuxAvailability({requireSessionEnv: true})
  return {
    launched: false,
    usedTmux: false,
    backend: 'exec',
    mode,
    toolPath,
    reason: `${tmux.reason ?? 'no available pane launcher'}; fallback disabled`,
  }
}

export {getTmuxAvailability, normalizeSplitFlag, quoteForSh, type TmuxAvailability, type TmuxSplitFlag} from './launchers/tmux-launcher.js'

/**
 * Helper to discover and invoke the `aiw` CLI binary from template scripts.
 *
 * Reads the resolved binary path from `.aiwcli/.aiw-bin-path` (written by `aiw init`).
 * Falls back to `aiw` on PATH if the file is missing.
 */

import * as fs from "node:fs";
import * as path from "node:path";

import { getProjectRoot } from "./constants.js";
import { execFileAsync, type ExecResult } from "./subprocess-utils.js";

function resolveAiwBin(cwd?: string): string {
  const projectRoot = getProjectRoot(cwd ?? process.cwd());
  const binPathFile = path.join(projectRoot, ".aiwcli", ".aiw-bin-path");
  try {
    const binPath = fs.readFileSync(binPathFile, "utf8").trim();
    if (binPath && fs.existsSync(binPath)) return binPath;
  } catch {
    // Fall through to PATH lookup
  }

  return "aiw";
}

export interface AiwLaunchOptions {
  /** Launch codex instead of claude. */
  codex?: boolean;
  /** Working directory. */
  cwd?: string;
  /** Extra env vars to inject. */
  env?: Record<string, string>;
  /** Return JSON output. */
  json?: boolean;
  /** Path to prompt file. */
  promptPath?: string;
  /** Split direction: auto, h, or v. */
  split?: "auto" | "h" | "v";
  /** Timeout in ms (only relevant with --wait). */
  timeoutMs?: number;
  /** Block until pane exits. */
  wait?: boolean;
}

export interface AiwLaunchResult {
  backend: string;
  exitCode: null | number;
  launched: boolean;
  paneId: null | string;
  reason: null | string;
  sentinelPath: null | string;
}

/**
 * Shell out to `aiw launch` with structured options.
 * Returns parsed JSON result when --json is used.
 */
export async function aiwLaunch(options: AiwLaunchOptions): Promise<AiwLaunchResult> {
  const bin = resolveAiwBin(options.cwd);
  const args = ["launch"];

  if (options.codex) args.push("--codex");
  if (options.wait) args.push("--wait");
  args.push("--json");
  if (options.split) args.push("--split", options.split);
  if (options.env && Object.keys(options.env).length > 0) {
    args.push("--env", JSON.stringify(options.env));
  }

  if (options.promptPath) args.push("--prompt-path", options.promptPath);

  const result = await execFileAsync(bin, args, {
    timeout: options.timeoutMs ?? 14_400_000,
    env: process.env as Record<string, string>,
    shell: process.platform === "win32",
  });

  return parseJsonResult(result);
}

function parseJsonResult(result: ExecResult): AiwLaunchResult {
  try {
    const lines = result.stdout.trim().split(/\r?\n/);
    const lastLine = lines.at(-1) ?? "";
    const parsed = JSON.parse(lastLine);
    return {
      launched: Boolean(parsed.launched),
      backend: String(parsed.backend ?? "exec"),
      paneId: parsed.paneId ?? null,
      sentinelPath: parsed.sentinelPath ?? null,
      exitCode: typeof parsed.exitCode === "number" ? parsed.exitCode : null,
      reason: parsed.reason ?? null,
    };
  } catch {
    return {
      launched: false,
      backend: "exec",
      paneId: null,
      sentinelPath: null,
      exitCode: result.exitCode,
      reason: `Failed to parse aiw launch output: ${result.stderr || result.stdout}`,
    };
  }
}

/**
 * Cross-platform atomic file writes with security.
 * Crash-safe writes by writing to temp file then renaming.
 * NOT for concurrent access — assumes single-session-per-context.
 * See SPEC.md §4
 */

import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as _os from "node:os";
import * as path from "node:path";

/**
 * Write file atomically with retry logic.
 * Creates temp file, writes, fsyncs, renames.
 * Returns [success, error].
 * See SPEC.md §4.2
 */
export function atomicWrite(
  filePath: string,
  content: string,
  maxAttempts = 2,
  backoffMs: number[] = [500, 1000],
): [boolean, null | string] {
  // Ensure parent directory exists
  const dir = path.dirname(filePath);
  fs.mkdirSync(dir, { recursive: true });

  const stem = path.basename(filePath, path.extname(filePath));

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const tmpName = `.${stem}_${crypto.randomBytes(4).toString("hex")}.tmp`;
    const tmpPath = path.join(dir, tmpName);

    try {
      // Write to temp file
      const fd = fs.openSync(tmpPath, "w");
      try {
        fs.writeSync(fd, content, undefined, "utf-8");
        fs.fsyncSync(fd);
      } finally {
        fs.closeSync(fd);
      }

      // Set restrictive permissions (best-effort)
      try {
        fs.chmodSync(tmpPath, 0o600);
      } catch {
        // May fail on some filesystems
      }

      // Atomic rename (cross-platform on modern Node/Bun)
      fs.renameSync(tmpPath, filePath);

      return [true, null];
    } catch (error: any) {
      // Clean up temp file
      try {
        fs.unlinkSync(tmpPath);
      } catch {
        // Best-effort cleanup
      }

      if (attempt < maxAttempts - 1) {
        const waitMs = backoffMs[Math.min(attempt, backoffMs.length - 1)] ?? backoffMs.at(-1) ?? 500;
        sleepSync(waitMs);
      } else {
        const errType = error?.constructor?.name ?? "Error";
        const errMsg = String(error).split("\n")[0]?.slice(0, 200) ?? "";
        return [false, `${errType}: ${errMsg}`];
      }
    }
  }

  return [false, "Max retry attempts exceeded"];
}

/**
 * Append to file with retry logic.
 * For JSONL files where each line is independent.
 * See SPEC.md §4.3
 */
export function atomicAppend(
  filePath: string,
  content: string,
  maxAttempts = 2,
  backoffMs: number[] = [500, 1000],
): [boolean, null | string] {
  // Ensure parent directory exists
  const dir = path.dirname(filePath);
  fs.mkdirSync(dir, { recursive: true });

  const isNewFile = !fs.existsSync(filePath);

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const fd = fs.openSync(filePath, "a");
      try {
        fs.writeSync(fd, content, undefined, "utf-8");
        fs.fsyncSync(fd);
      } finally {
        fs.closeSync(fd);
      }

      // Set permissions on newly created files (best-effort)
      if (isNewFile) {
        try {
          fs.chmodSync(filePath, 0o600);
        } catch {
          // May fail on some filesystems
        }
      }

      return [true, null];
    } catch (error: any) {
      if (attempt < maxAttempts - 1) {
        const waitMs = backoffMs[Math.min(attempt, backoffMs.length - 1)] ?? backoffMs.at(-1) ?? 500;
        sleepSync(waitMs);
      } else {
        const errType = error?.constructor?.name ?? "Error";
        const errMsg = String(error).split("\n")[0]?.slice(0, 200) ?? "";
        return [false, `${errType}: ${errMsg}`];
      }
    }
  }

  return [false, "Max retry attempts exceeded"];
}

/**
 * Synchronous sleep for retry backoff.
 * Uses Atomics.wait() for CPU-friendly blocking instead of busy-wait.
 */
function sleepSync(ms: number): void {
  const sab = new SharedArrayBuffer(4);
  const i32 = new Int32Array(sab);
  Atomics.wait(i32, 0, 0, ms);
}

/**
 * Centralized CLI argument construction for agent subprocesses.
 * Single source of truth for Claude CLI and Codex CLI flag patterns,
 * platform quoting, model tier resolution, and env setup.
 */

import { CLAUDE_MODELS, CODEX_MODELS } from "./models.js";
import type { PreflightCommandConfig } from "./preflight.js";
import { getInternalSubprocessEnv, shellQuoteWin } from "./subprocess-utils.js";



// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type InvocationMode = "preflight" | "print" | "structured";
export type CliProvider = "claude" | "codex";
export type ModelTier = "fast" | "smart" | "standard";

const VALID_SANDBOXES = ["read-only", "workspace-write", "danger-full-access"] as const;
export type CodexSandbox = (typeof VALID_SANDBOXES)[number];

export function isCodexSandbox(value: string): value is CodexSandbox {
  return (VALID_SANDBOXES as readonly string[]).includes(value);
}

export interface CliArgSpec {
  extraArgs?: string[];
  jsonSchema?: Record<string, unknown>;
  maxTurns?: number;
  mode: InvocationMode;
  model: ModelTier | string;
  outputFilePath?: string;
  outputSchemaPath?: string;
  provider: CliProvider;
  sandbox?: CodexSandbox;
  systemPrompt?: string;
}

/** Codex REPL spec — model optional (Codex uses its default when omitted). */
export interface CodexReplSpec {
  extraArgs?: string[];
  mode: "repl";
  model?: ModelTier | string;
  provider: "codex";
  sandbox?: CodexSandbox;
  yolo?: boolean;
}

export interface CliInvocation {
  args: string[];
  cliName: string;
  env: Record<string, string | undefined>;
  needsShell: boolean;
}

// ---------------------------------------------------------------------------
// Model Tier Resolution
// ---------------------------------------------------------------------------

export const MODEL_TIERS: Record<ModelTier, string> = {
  fast: CLAUDE_MODELS.haiku,
  standard: CLAUDE_MODELS.sonnet,
  smart: CLAUDE_MODELS.opus,
};

export const CODEX_MODEL_TIERS: Record<ModelTier, string> = {
  fast: CODEX_MODELS.spark,
  standard: CODEX_MODELS.codex,
  smart: CODEX_MODELS.codex,
};

export const TIER_TIMEOUTS: Record<ModelTier, number> = {
  fast: 15,
  standard: 30,
  smart: 90,
};

export function isModelTier(value: string): value is ModelTier {
  return value in MODEL_TIERS;
}

export function resolveModel(model: ModelTier | string): string {
  if (isModelTier(model)) return MODEL_TIERS[model];
  return model;
}

export function resolveModelForProvider(
  model: ModelTier | string,
  provider: CliProvider,
): string {
  if (!isModelTier(model)) return model;
  return provider === "codex" ? CODEX_MODEL_TIERS[model] : MODEL_TIERS[model];
}

export function getTierTimeout(tier: ModelTier): number {
  return TIER_TIMEOUTS[tier];
}

/** Resolve a Codex model: tier resolution + pass-through. No aliases (those are skill-specific). */
export function resolveCodexModel(input: string): string {
  if (isModelTier(input)) return CODEX_MODEL_TIERS[input as ModelTier];
  return input;
}

// ---------------------------------------------------------------------------
// Core Builder
// ---------------------------------------------------------------------------

export function buildCliInvocation(spec: CliArgSpec | CodexReplSpec): CliInvocation {
  const env = getInternalSubprocessEnv();
  delete env.ANTHROPIC_API_KEY;

  if (spec.mode === "repl") {
    const resolvedModel = spec.model ? resolveModelForProvider(spec.model, spec.provider) : undefined;
    return buildCodexReplInvocation(spec, resolvedModel, env);
  }

  const resolvedModel = resolveModelForProvider((spec as CliArgSpec).model, spec.provider);
  const isWin = process.platform === "win32";
  const empty = isWin ? '""' : "";

  if (spec.provider === "claude") {
    return buildClaudeInvocation(spec as CliArgSpec, resolvedModel, isWin, empty, env);
  }

  return buildCodexInvocation(spec as CliArgSpec, resolvedModel, env);
}

function buildClaudeInvocation(
  spec: CliArgSpec,
  model: string,
  isWin: boolean,
  empty: string,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = [];

  args.push("--model", model);

  if (spec.mode === "print") {
    args.push("--print");
  } else {
    // structured and preflight both use json output
    args.push("--output-format", "json");

    if (spec.jsonSchema) {
      args.push("--json-schema", shellQuoteWin(JSON.stringify(spec.jsonSchema)));
    }

    const maxTurns = spec.mode === "preflight" ? 1 : (spec.maxTurns ?? 3);
    args.push("--max-turns", String(maxTurns));
  }

  args.push("--setting-sources", empty, "-p", "--no-session-persistence");

  if (spec.systemPrompt) {
    args.push("--system-prompt", shellQuoteWin(spec.systemPrompt));
  }

  if (spec.extraArgs) {
    args.push(...spec.extraArgs);
  }

  return { cliName: "claude", args, needsShell: isWin, env };
}

function buildCodexInvocation(
  spec: CliArgSpec,
  model: string,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = ["exec"];

  if (spec.sandbox) {
    args.push("--sandbox", spec.sandbox);
  }

  args.push("--model", model);

  if (spec.outputSchemaPath) {
    args.push("--output-schema", spec.outputSchemaPath);
  }

  if (spec.outputFilePath) {
    args.push("-o", spec.outputFilePath);
  }

  args.push("-");

  if (spec.extraArgs) {
    args.push(...spec.extraArgs);
  }

  return { cliName: "codex", args, needsShell: false, env };
}

function buildCodexReplInvocation(
  spec: CodexReplSpec,
  model: string | undefined,
  env: Record<string, string | undefined>,
): CliInvocation {
  const args: string[] = [];
  if (spec.yolo) args.push("--dangerously-bypass-approvals-and-sandbox");
  if (spec.sandbox) args.push("--sandbox", spec.sandbox);
  if (model) args.push("--model", model);
  if (spec.extraArgs) args.push(...spec.extraArgs);
  return { cliName: "codex", args, needsShell: false, env };
}

// ---------------------------------------------------------------------------
// Convenience Presets
// ---------------------------------------------------------------------------

export function preflightSpec(provider: CliProvider, model: string): CliArgSpec {
  if (provider === "codex") {
    return {
      provider: "codex",
      model,
      mode: "preflight",
      sandbox: "read-only",
    };
  }

  return {
    provider: "claude",
    model,
    mode: "preflight",
  };
}

export function inferenceSpec(model: ModelTier | string): CliArgSpec {
  return {
    provider: "claude",
    model,
    mode: "print",
  };
}

export function reviewSpec(
  provider: CliProvider,
  model: string,
  schema: Record<string, unknown>,
  systemPrompt?: string,
): CliArgSpec {
  if (provider === "codex") {
    return {
      provider: "codex",
      model,
      mode: "structured",
      sandbox: "read-only",
    };
  }

  return {
    provider: "claude",
    model,
    mode: "structured",
    jsonSchema: schema,
    ...(systemPrompt ? {systemPrompt} : {}),
  };
}

export function codexReplSpec(
  model?: string,
  sandbox?: CodexSandbox,
  yolo?: boolean,
): CodexReplSpec {
  return {
    provider: "codex",
    mode: "repl",
    ...(model ? {model} : {}),
    ...(sandbox ? {sandbox} : {}),
    ...(yolo === undefined ? {} : {yolo}),
  };
}

export function preflightCommandConfig(provider: CliProvider): PreflightCommandConfig {
  const input = "Respond with exactly: ok";

  return {
    cliName: provider === "claude" ? "claude" : "codex",
    buildArgs: (model: string) => buildCliInvocation(preflightSpec(provider, model)).args,
    input,
  };
}

export {CLAUDE_MODELS, CODEX_MODELS} from "./models.js";

/**
 * Constants and path utilities for shared context management.
 * See SPEC.md §2
 */

import * as fs from "node:fs";
import * as path from "node:path";

import { logWarn } from "./logger.js";

// Directory names (relative to project root)
const OUTPUT_DIR = "_output";
const CONTEXTS_DIR = "contexts";
const ARCHIVE_DIR = "_archive";
const INDEX_FILENAME = "index.json";

// Context ID validation
export const MAX_CONTEXT_ID_LENGTH = 64;
export const VALID_CONTEXT_ID_PATTERN =
  /^[a-z0-9][a-z0-9_-]*[a-z0-9]$|^[a-z0-9]$/;

// File size limits
export const MAX_EVENT_SIZE = 64 * 1024;
export const MAX_INDEX_SIZE = 1024 * 1024;

// Performance constants
export const MAX_RETRY_ATTEMPTS = 2;
export const RETRY_BACKOFF_MS = [500, 1000];

// Windows reserved filenames
const WINDOWS_RESERVED = new Set([
  "AUX", "COM1", "COM2", "COM3",
  "COM4", "COM5", "COM6", "COM7", "COM8", "COM9", "CON", "LPT1", "LPT2",
  "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9", "NUL", "PRN",
]);

/**
 * Sanitize a string into a valid context ID.
 * See SPEC.md §2.3
 */
export function sanitizeContextId(contextId: string): string {
  if (!contextId) return "context";

  let result = contextId.toLowerCase();
  result = result.replaceAll(/[^a-z0-9_-]/g, "-");
  result = result.replaceAll(/[-_]+/g, "-");
  result = result.replaceAll(/^[-_]+|[-_]+$/g, "");

  if (result.length > MAX_CONTEXT_ID_LENGTH) {
    result = result.slice(0, MAX_CONTEXT_ID_LENGTH).replace(/[-_]+$/, "");
  }

  return result || "context";
}

/**
 * Validate and normalize context ID.
 * Throws only for security violations (path traversal).
 * See SPEC.md §2.3
 */
export function validateContextId(contextId: string): string {
  if (!contextId) return "context";

  // SECURITY: Check for path traversal BEFORE any normalization
  if (
    contextId.includes("..") ||
    contextId.includes("/") ||
    contextId.includes("\\")
  ) {
    throw new Error(
      `Invalid context ID '${contextId}': path traversal not allowed`,
    );
  }

  // Check for URL-encoded variants
  const lower = contextId.toLowerCase();
  if (
    lower.includes("%2e") ||
    lower.includes("%2f") ||
    lower.includes("%5c")
  ) {
    throw new Error(
      `Invalid context ID '${contextId}': encoded path traversal not allowed`,
    );
  }

  return sanitizeContextId(contextId);
}

/**
 * Walk up from startDir until a directory containing `.aiwcli/` is found.
 * Returns startDir itself if no anchor is found (fail-safe).
 * See SPEC.md §2.2
 */
function findProjectRoot(startDir: string): string {
  let dir = startDir;
  while (true) {
    if (fs.existsSync(path.join(dir, ".aiwcli"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break; // filesystem root reached
    dir = parent;
  }

  return startDir; // fallback: no .aiwcli anchor found
}

/**
 * Get project root from environment or cwd.
 * Priority: CLAUDE_PROJECT_DIR > walk up from payload cwd > walk up from process.cwd()
 * Walks upward to find the nearest .aiwcli/ anchor, so cwd drift (e.g. after
 * `cd packages/cli` in a Bash tool call) doesn't break hook resolution.
 * See SPEC.md §2.2
 */
export function getProjectRoot(payloadCwd?: string): string {
  const envDir = process.env.CLAUDE_PROJECT_DIR;
  if (envDir) {
    if (!path.isAbsolute(envDir)) {
      logWarn("utils", `CLAUDE_PROJECT_DIR is not absolute: '${envDir}', ignoring`);
    } else if (envDir.includes("..")) {
      logWarn("utils", `CLAUDE_PROJECT_DIR contains '..': '${envDir}', ignoring`);
    } else {
      return envDir;
    }
  }

  if (payloadCwd) return findProjectRoot(payloadCwd);
  return findProjectRoot(process.cwd());
}

// §2.4 — Path functions

export function getAiwcliDir(projectRoot?: string): string {
  return path.join(projectRoot ?? getProjectRoot(), ".aiwcli");
}

export function getOutputDir(projectRoot?: string): string {
  return path.join(projectRoot ?? getProjectRoot(), OUTPUT_DIR);
}

export function getContextsDir(projectRoot?: string): string {
  return path.join(getOutputDir(projectRoot), CONTEXTS_DIR);
}

export function getContextDir(
  contextId: string,
  projectRoot?: string,
): string {
  const validatedId = validateContextId(contextId);
  const contextsDir = getContextsDir(projectRoot);
  const resultPath = path.join(contextsDir, validatedId);

  // SECURITY: Verify resolved path stays within contexts directory
  const resolved = path.resolve(resultPath);
  const contextsResolved = path.resolve(contextsDir);
  if (
    !resolved.toLowerCase().startsWith(contextsResolved.toLowerCase())
  ) {
    throw new Error(
      `Invalid context ID '${contextId}': path escapes contexts directory`,
    );
  }

  return resultPath;
}

