/**
 * Get path for a new handoff folder with datetime naming.
 * Handles collisions by appending -N suffix.
 * See SPEC.md §2.4
 */
export function getHandoffFolderPath(
  contextId: string,
  projectRoot?: string,
): string {
  const handoffsDir = getContextHandoffsDir(contextId, projectRoot);
  const now = new Date();
  const timestamp = [
    now.getFullYear().toString(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
    "-",
    String(now.getHours()).padStart(2, "0"),
    String(now.getMinutes()).padStart(2, "0"),
  ].join("");
  // Format: YYYY-MM-DD-HHMM
  const ts = `${timestamp.slice(0, 4)}-${timestamp.slice(4, 6)}-${timestamp.slice(6, 8)}${timestamp.slice(8)}`;

  let folder = path.join(handoffsDir, ts);
  let counter = 1;
  while (fs.existsSync(folder)) {
    folder = path.join(handoffsDir, `${ts}-${counter}`);
    counter++;
  }

  return folder;
}

/**
 * Get path for a new review folder.
 * See SPEC.md §2.4
 */
export function getReviewFolderPath(
  contextId: string,
  iteration: number,
  projectRoot?: string,
): string {
  const reviewsDir = path.join(
    getContextReviewsDir(contextId, projectRoot),
    "cc-native",
  );
  const now = new Date();
  const ts = [
    now.getFullYear().toString(),
    "-",
    String(now.getMonth() + 1).padStart(2, "0"),
    "-",
    String(now.getDate()).padStart(2, "0"),
    "-",
    String(now.getHours()).padStart(2, "0"),
    String(now.getMinutes()).padStart(2, "0"),
  ].join("");
  return path.join(reviewsDir, `${ts}-iteration-${iteration}`);
}

// §2.5 — Filename sanitization

export function sanitizeFilename(
  s: string,
  maxLen = 32,
  allowLeadingDot = false,
): string {
  let result = s.replaceAll(/[^A-Za-z0-9._-]+/g, "_");
  result = result.replaceAll(/^[._-]+|[._-]+$/g, "").slice(0, maxLen) || "unknown";

  if (!allowLeadingDot) {
    result = result.replace(/^\.+/, "");
  }

  const baseName = (result.split(".")[0] ?? result).toUpperCase();
  if (WINDOWS_RESERVED.has(baseName)) {
    result = `_${result}`;
  }

  return result || "unknown";
}

export function sanitizeTitle(s: string, maxLen = 50): string {
  let result = s.toLowerCase().trim();
  result = result.replaceAll(' ', "-");
  result = result.replaceAll(/[^a-z0-9._-]+/g, "_");
  result = result.replaceAll(/[-_]+/g, "-");
  result = result.replaceAll(/^[._-]+|[._-]+$/g, "").slice(0, maxLen) || "unknown";

  const baseName = (result.split(".")[0] ?? result).toUpperCase();
  if (WINDOWS_RESERVED.has(baseName)) {
    result = `_${result}`;
  }

  return result || "unknown";
}

import { execSync } from 'node:child_process'
import type { ExecSyncOptionsWithStringEncoding } from 'node:child_process'

import { commandLookupBinary, isWindowsPlatform } from './platform-adapter.js'

export type WindowsLookupProfile = 'cmdOrExeFirst' | 'exeThenExtensionlessThenCmd'

export function parseLookupLines(stdout: string): string[] {
  return stdout
    .trim()
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
}

export function pickWindowsPath(lines: string[], profile: WindowsLookupProfile): null | string {
  if (lines.length === 0) return null

  if (profile === 'cmdOrExeFirst') {
    return lines.find((line) => /\.(cmd|exe)$/i.test(line)) ?? lines[0] ?? null
  }

  return lines.find((line) => /\.exe$/i.test(line))
    ?? lines.find((line) => !/\.(cmd|ps1)$/i.test(line))
    ?? lines.find((line) => /\.cmd$/i.test(line))
    ?? lines[0]
    ?? null
}

export function selectLookupPath(
  lines: string[],
  platform: NodeJS.Platform = process.platform,
  windowsProfile: WindowsLookupProfile = 'cmdOrExeFirst',
): null | string {
  if (lines.length === 0) return null
  if (!isWindowsPlatform(platform)) return lines[0] ?? null
  return pickWindowsPath(lines, windowsProfile)
}

export function resolveExecutable(
  name: string,
  options?: {
    platform?: NodeJS.Platform | undefined
    timeoutMs?: number | undefined
    windowsHide?: boolean | undefined
    windowsProfile?: undefined | WindowsLookupProfile
  },
): null | string {
  const platform = options?.platform ?? process.platform
  const lines = lookupExecutables(name, {
    platform,
    timeoutMs: options?.timeoutMs,
    windowsHide: options?.windowsHide,
  })
  return selectLookupPath(lines, platform, options?.windowsProfile ?? 'cmdOrExeFirst')
}

export function isCommandAvailable(
  name: string,
  platform: NodeJS.Platform = process.platform,
): boolean {
  return resolveExecutable(name, { platform }) !== null
}

export function lookupExecutables(
  name: string,
  options?: {
    platform?: NodeJS.Platform | undefined
    timeoutMs?: number | undefined
    windowsHide?: boolean | undefined
  },
): string[] {
  const platform = options?.platform ?? process.platform
  const lookupBin = commandLookupBinary(platform)
  const cmd = `${lookupBin} ${name}`

  try {
    return parseLookupLines(execSync(cmd, {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
      shell: true,
      timeout: options?.timeoutMs ?? 3000,
      windowsHide: options?.windowsHide ?? true,
    } as unknown as ExecSyncOptionsWithStringEncoding))
  } catch {
    return []
  }
}

import { execFileSync } from "node:child_process";

/**
 * Capture current git state for session snapshots.
 * All fields are optional — failures are silently ignored.
 */
export function getGitState(projectRoot: string): Record<string, any> {
  const gitState: Record<string, any> = {};
  const isWin = process.platform === "win32";
  const opts = {
    cwd: projectRoot,
    timeout: 5000,
    encoding: "utf-8" as const,
    stdio: ["pipe", "pipe", "pipe"] as ["pipe", "pipe", "pipe"],
    shell: isWin,
  };

  try {
    const branch = execFileSync("git", ["rev-parse", "--abbrev-ref", "HEAD"], opts);
    if (branch) gitState.branch = branch.trim();
  } catch { /* non-fatal */ }

  try {
    const status = execFileSync("git", ["status", "--short"], opts);
    if (status) {
      const files = status.trim().split(/\r?\n/)
        .filter(Boolean)
        .slice(0, 10)
        .map(line => line.trimStart().split(/\s+/).slice(1).join(" "));
      if (files.length > 0) gitState.uncommitted_files = files;
    }
  } catch { /* non-fatal */ }

  try {
    const log = execFileSync("git", ["log", "-1", "--oneline"], opts);
    if (log) gitState.last_commit_short = log.trim();
  } catch { /* non-fatal */ }

  return gitState;
}

/**
 * Get short git status string for display (e.g., in handoff documents).
 */
export function getGitStatusShort(projectRoot?: string): string {
  try {
    const result = execFileSync("git", ["status", "--short"], {
      encoding: "utf-8",
      timeout: 5000,
      stdio: ["pipe", "pipe", "pipe"],
      ...(projectRoot ? { cwd: projectRoot } : {}),
      shell: process.platform === "win32",
    });
    return result.trim() || "(no changes)";
  } catch {
    return "(git status unavailable)";
  }
}

/**
 * Inference utility for AI-powered text processing.
 * Unified interface for Claude API calls using the claude CLI.
 * See SPEC.md §6
 */

import { execFileSync } from "node:child_process";

import { logDebug, logWarn } from "./logger.js";
import { STOP_WORDS } from "./stop-words.js";
import type { InferenceResult } from "../types.js";
import {
  buildCliInvocation,
  getTierTimeout,
  inferenceSpec,
  isModelTier,
  resolveModel,
  TIER_TIMEOUTS,
} from "./cli-args.js";
import { CODEX_MODELS } from "./models.js";
import { execFileAsync } from "./subprocess-utils.js";

const CONTEXT_ID_PRIMARY_MODEL = CODEX_MODELS.spark;

/**
 * Run inference using the claude CLI.
 * See SPEC.md §6.1
 */
export function inference(
  systemPrompt: string,
  userPrompt: string,
  level = "fast",
  timeout?: number,
  options?: { model?: string },
): InferenceResult {
  const startTime = Date.now();
  const modelInput = options?.model ?? level;
  const timeoutSec = timeout ?? (isModelTier(modelInput) ? getTierTimeout(modelInput) : TIER_TIMEOUTS.fast);
  const fullPrompt = `${systemPrompt}\n\n${userPrompt}`;

  const invocation = buildCliInvocation(inferenceSpec(modelInput));
  const isWin = invocation.needsShell;

  // Prompt arg needs Windows quoting when using shell mode
  let promptArg = fullPrompt;
  if (isWin) {
    promptArg = '"' + fullPrompt.replaceAll(/\r?\n/g, " ").replaceAll('"', '""') + '"';
  }

  try {
    const stdout = execFileSync(
      invocation.cliName,
      [...invocation.args, promptArg],
      {
        timeout: timeoutSec * 1000,
        env: invocation.env,
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "pipe"],
        shell: isWin,
      },
    );

    const latencyMs = Date.now() - startTime;
    return {
      success: true,
      output: stdout.trim(),
      latency_ms: latencyMs,
    };
  } catch (error: any) {
    const latencyMs = Date.now() - startTime;

    if (error.code === "ETIMEDOUT" || error.killed) {
      return {
        success: false,
        output: "",
        error: `Timeout after ${timeoutSec}s`,
        latency_ms: latencyMs,
      };
    }

    if (error.code === "ENOENT") {
      return {
        success: false,
        output: "",
        error: "claude CLI not found",
        latency_ms: latencyMs,
      };
    }

    // Non-zero exit code
    if (error.status !== undefined && error.status !== 0) {
      return {
        success: false,
        output: (error.stdout ?? "").toString().trim(),
        error: (error.stderr ?? "").toString().trim() || `Exit code: ${error.status}`,
        latency_ms: latencyMs,
      };
    }

    return {
      success: false,
      output: "",
      error: String(error),
      latency_ms: latencyMs,
    };
  }
}

// §6.2 — System prompt for keyword extraction
const CONTEXT_ID_SYSTEM_PROMPT = `Extract 6-12 keywords from what the user wants to do.

Rules:
- Output 6-12 keywords only
- Keywords: nouns, verbs, adjectives, technical terms, proper names
- NO function words: the, to, with, for, in, a, an, of, on, is, it, and, or, that, this, be, as, at, by, from
- Most important/specific words preferred
- No punctuation, no quotes

Output ONLY the keywords separated by spaces, nothing else.`;

/**
 * Generate a keyword summary of a user prompt.
 * Uses Sonnet (standard tier). Returns null if inference fails.
 * See SPEC.md §6.2
 */
export function generateSemanticSummary(
  prompt: string,
  timeout = 15,
): null | string {
  const result = inference(CONTEXT_ID_SYSTEM_PROMPT, prompt, "standard", timeout);

  if (!result.success || !result.output) return null;

  let summary = result.output.trim();
  summary = summary.replaceAll(/^["']+|["']+$/g, "");
  summary = summary.replace(/[.!?]+$/, "");

  // Filter stop words
  summary = filterStopWords(summary);

  const words = summary.split(/\s+/);
  if (words.length < 6 || words.length > 12) return null;

  return summary;
}

// §6.3 — System prompt for context ID slug generation
const CONTEXT_ID_SLUG_PROMPT = `You generate short title phrases for work sessions. These become folder names like \`260206-1959-fix-auth-middleware-redirect-loop-session-timeout\`.

Users scan 100+ such names to find past sessions. Your title must make THIS session instantly recognizable.

Rules:
- Exactly 8-12 lowercase words
- First word is an action verb (fix, add, implement, refactor, update, create, remove, optimize, debug, migrate, integrate, configure, deploy, scaffold, restructure)
- Coherent phrase, not disjointed keywords — reads like a short task description
- Prefer specific technical terms over generic words
- No articles (the, a, an), no pronouns, no filler words, no punctuation, no quotes
- Input may come from speech-to-text with filler words (uh, um, like, you know, basically, so) — ignore them entirely

Examples:

Input: "um so basically I need to like fix the auth bug in the login page"
{"slug": "fix authentication bug login page redirect session handling flow"}

Input: "hey uh can we add dark mode to the settings page"
{"slug": "add dark mode toggle settings page user preference storage"}

Input: "the context ids are bad can we change how we generate them towards a summary"
{"slug": "improve context id generation use prompt summary slugs"}

Input: "I want to refactor the database connection pooling for PostgreSQL"
{"slug": "refactor postgresql database connection pooling optimize query performance"}

Input: "so like you know the webhook retry logic is broken and stuff"
{"slug": "fix webhook retry logic broken error handling recovery mechanism"}

Input: "update the CI pipeline to cache node modules between runs"
{"slug": "update ci pipeline cache node modules between workflow runs"}

Respond with ONLY a JSON object: {"slug": "your 8-12 word phrase here"}`;

/**
 * Generate a 5-12 word context ID slug from a user prompt.
 * Uses 5.3 Codex Spark first, then falls back to current fast tier for resilience.
 * See SPEC.md §6.3
 */
export function generateContextIdSlug(
  prompt: string,
  timeout = 3,
): null | string {
  const truncated = prompt.slice(0, 500);

  const sparkResult = inference(
    CONTEXT_ID_SLUG_PROMPT,
    truncated,
    "fast",
    timeout,
    { model: CONTEXT_ID_PRIMARY_MODEL },
  );
  if (!sparkResult.success || !sparkResult.output) {
    logWarn(
      "inference",
      `Context ID slug Spark (${CONTEXT_ID_PRIMARY_MODEL}) failed or returned empty output. Falling back to ${resolveModel("fast")}`,
    );
  }

  const result = sparkResult.success && sparkResult.output ? sparkResult : inference(CONTEXT_ID_SLUG_PROMPT, truncated, "fast", timeout);

  if (!result.success || !result.output) {
    logWarn("inference", `Context ID slug inference failed: ${result.error}`);
    return null;
  }

  const raw = result.output.trim();

  // Parse JSON response, fall back to raw text
  let slug: null | string = null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object" && "slug" in parsed) {
      slug = parsed.slug;
    }
  } catch {
    // Fall through to raw text
  }

  if (!slug) slug = raw;

  // Clean up
  slug = slug.replaceAll(/^["'`]+|["'`]+$/g, "");
  slug = slug.replace(/[.!?]+$/, "");
  slug = slug.replaceAll('-', " ");
  slug = slug.replaceAll(/[^a-zA-Z0-9 ]/g, "");
  slug = slug.replaceAll(/\s+/g, " ").trim();

  const words = slug.split(" ");

  if (words.length > 12) words.length = 12;
  if (words.length < 5) {
    logDebug("inference", `Context ID slug too short (${words.length} words): '${slug}'`);
    return null;
  }

  const resultSlug = words.join(" ");
  logDebug("inference", `Generated context ID slug: '${resultSlug}' (${result.latency_ms}ms)`);
  return resultSlug;
}

/**
 * Async version of inference() that does NOT block the event loop.
 * Use for parallel AI calls (e.g., Stage 3 parallel summarizers).
 * Uses execFileAsync and getInternalSubprocessEnv for proper subprocess isolation.
 */
export async function inferenceAsync(
  systemPrompt: string,
  userPrompt: string,
  level = "fast",
  timeout?: number,
  options?: { model?: string },
): Promise<InferenceResult> {
  const startTime = Date.now();
  const modelInput = options?.model ?? level;
  const timeoutSec = timeout ?? (isModelTier(modelInput) ? getTierTimeout(modelInput) : TIER_TIMEOUTS.fast);
  const timeoutMs = timeoutSec * 1000;
  const fullPrompt = `${systemPrompt}\n\n${userPrompt}`;

  const invocation = buildCliInvocation(inferenceSpec(modelInput));
  const isWin = invocation.needsShell;

  // Prompt arg needs Windows quoting when using shell mode
  const promptArg = isWin
    ? ('"' + fullPrompt.replaceAll(/\r?\n/g, " ").replaceAll('"', '""') + '"')
    : fullPrompt;

  const result = await execFileAsync(
    invocation.cliName,
    [...invocation.args, promptArg],
    { timeout: timeoutMs, env: invocation.env, shell: isWin },
  );

  const latencyMs = Date.now() - startTime;

  if (result.killed) {
    return { success: false, output: "", error: `Timeout after ${timeoutSec}s`, latency_ms: latencyMs };
  }

  if (result.exitCode !== 0) {
    return {
      success: false,
      output: result.stdout.trim(),
      error: result.stderr.trim() || `Exit code: ${result.exitCode}`,
      latency_ms: latencyMs,
    };
  }

  return { success: true, output: result.stdout.trim(), latency_ms: latencyMs };
}

/**
 * Filter stop words from text.
 * See SPEC.md §6.4
 */
function filterStopWords(text: string): string {
  return text
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => !STOP_WORDS.has(w) && w.length > 1)
    .join(" ");
}

/**
 * Linter dispatch table and runner for PostToolUse lint-after-edit hook.
 * Maps file extensions to linter configs, runs linters, parses output.
 * See root CLAUDE.md for template sync targets.
 */

import {spawnSync} from 'node:child_process'
import * as fs from "node:fs";
import * as path from "node:path";

import { logDebug, logWarn } from "./logger.js";
import { findExecutable } from "./subprocess-utils.js";

// ─── Types ──────────────────────────────────────────────────────────────────

export interface LinterConfig {
  binaryName: string;
  buildArgs: (filePath: string) => string[];
  extensions: string[];
  /** Exit codes that mean "lint errors found" (parse output). Other non-zero = crash (skip). */
  lintExitCodes: number[];
  name: string;
  parseOutput: (stdout: string, stderr: string, exitCode: number) => LintError[];
  source: "bundled" | "system";
}

export interface LintError {
  column?: number;
  line: number;
  message: string;
  rule?: string;
  severity: "error" | "warning";
}

// ─── Output Parsers ─────────────────────────────────────────────────────────

function parseBiomeOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  try {
    const data = JSON.parse(stdout);
    const diagnostics: any[] = data?.diagnostics ?? [];
    return diagnostics.map((d) => ({
      line: d.location?.span?.start?.line ?? d.location?.sourceCode?.lineIndex ?? 0,
      column: d.location?.span?.start?.character ?? undefined,
      severity: d.severity === "error" || d.severity === "fatal" ? "error" as const : "warning" as const,
      message: typeof d.description === "string" ? d.description : (d.message ?? "Unknown issue"),
      ...(d.category ? {rule: d.category} : {}),
    }));
  } catch {
    return [];
  }
}

function parseRuffOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  try {
    const items: any[] = JSON.parse(stdout);
    return items.map((item) => ({
      line: item.location?.row ?? 0,
      column: item.location?.column ?? undefined,
      severity: "error" as const,
      message: item.message ?? "Unknown issue",
      ...(item.code ? {rule: item.code} : {}),
    }));
  } catch {
    return [];
  }
}

function parseShellcheckOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  try {
    const data = JSON.parse(stdout);
    const comments: any[] = data?.comments ?? [];
    return comments.map((c) => ({
      line: c.line ?? 0,
      column: c.column ?? undefined,
      severity: c.level === "error" ? "error" as const : "warning" as const,
      message: c.message ?? "Unknown issue",
      ...(c.code ? {rule: `SC${c.code}`} : {}),
    }));
  } catch {
    return [];
  }
}

function parseRubocopOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  try {
    const data = JSON.parse(stdout);
    const offenses: any[] = data?.files?.[0]?.offenses ?? [];
    return offenses.map((o) => ({
      line: o.location?.line ?? 0,
      column: o.location?.column ?? undefined,
      severity: o.severity === "error" || o.severity === "fatal" ? "error" as const : "warning" as const,
      message: o.message ?? "Unknown issue",
      ...(o.cop_name ? {rule: o.cop_name} : {}),
    }));
  } catch {
    return [];
  }
}

const CPPCHECK_RE = /^(.+):(\d+):(\d+): (\w+): (.+) \[(.+)\]$/;

function parseCppcheckOutput(_stdout: string, stderr: string, _exitCode: number): LintError[] {
  const errors: LintError[] = [];
  for (const line of stderr.split("\n")) {
    const m = CPPCHECK_RE.exec(line.trim());
    if (m) {
      errors.push({
        line: Number.parseInt(m[2]!, 10),
        column: Number.parseInt(m[3]!, 10),
        severity: m[4] === "error" ? "error" : "warning",
        message: m[5]!,
        ...(m[6] ? {rule: m[6]} : {}),
      });
    }
  }

  return errors;
}

function parseEslintOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  try {
    const files: any[] = JSON.parse(stdout);
    const messages: any[] = files?.[0]?.messages ?? [];
    return messages.map((m) => ({
      line: m.line ?? 0,
      column: m.column ?? undefined,
      severity: m.severity === 2 ? "error" as const : "warning" as const,
      message: m.message ?? "Unknown issue",
      ...(m.ruleId ? {rule: m.ruleId} : {}),
    }));
  } catch {
    return [];
  }
}

const RUSTFMT_DIFF_RE = /^Diff in (.+) at line (\d+)/;

function parseRustfmtOutput(stdout: string, _stderr: string, _exitCode: number): LintError[] {
  const errors: LintError[] = [];
  for (const line of stdout.split("\n")) {
    const m = RUSTFMT_DIFF_RE.exec(line.trim());
    if (m) {
      errors.push({
        line: Number.parseInt(m[2]!, 10),
        severity: "warning",
        message: "Formatting differs from rustfmt style",
        rule: "rustfmt",
      });
    }
  }

  return errors;
}

// ─── Dispatch Table ─────────────────────────────────────────────────────────

const LINTERS: LinterConfig[] = [
  {
    name: "biome",
    extensions: [".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".json", ".jsonc", ".css"],
    source: "bundled",
    binaryName: "biome",
    buildArgs: (filePath) => ["lint", "--reporter=json", "--max-diagnostics=20", filePath],
    parseOutput: parseBiomeOutput,
    lintExitCodes: [1],
  },
  {
    name: "ruff",
    extensions: [".py", ".pyi"],
    source: "system",
    binaryName: "ruff",
    buildArgs: (filePath) => ["check", "--no-fix", "--output-format=json", filePath],
    parseOutput: parseRuffOutput,
    lintExitCodes: [1],
  },
  {
    name: "shellcheck",
    extensions: [".sh", ".bash"],
    source: "system",
    binaryName: "shellcheck",
    buildArgs: (filePath) => ["-f", "json1", filePath],
    parseOutput: parseShellcheckOutput,
    lintExitCodes: [1],
  },
  {
    name: "rubocop",
    extensions: [".rb"],
    source: "system",
    binaryName: "rubocop",
    buildArgs: (filePath) => ["--format", "json", "--no-autocorrect", filePath],
    parseOutput: parseRubocopOutput,
    lintExitCodes: [1, 2],
  },
  {
    name: "cppcheck",
    extensions: [".c", ".cpp", ".h", ".hpp"],
    source: "system",
    binaryName: "cppcheck",
    buildArgs: (filePath) => ["--enable=warning,style", "--template=gcc", filePath],
    parseOutput: parseCppcheckOutput,
    lintExitCodes: [1],
  },
  {
    name: "eslint",
    extensions: [".svelte"],
    source: "system",
    binaryName: "eslint",
    buildArgs: (filePath) => ["--format", "json", "--no-fix", filePath],
    parseOutput: parseEslintOutput,
    lintExitCodes: [1],
  },
  {
    name: "rustfmt",
    extensions: [".rs"],
    source: "system",
    binaryName: "rustfmt",
    buildArgs: (filePath) => ["--check", filePath],
    parseOutput: parseRustfmtOutput,
    lintExitCodes: [1],
  },
];

/** Extension → LinterConfig lookup map (built once). */
const EXT_MAP = new Map<string, LinterConfig>();
for (const linter of LINTERS) {
  for (const ext of linter.extensions) {
    EXT_MAP.set(ext, linter);
  }
}

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Look up the linter config for a file by extension.
 * Returns null if no linter is configured for this file type.
 */
export function getLinterForFile(filePath: string): LinterConfig | null {
  const ext = path.extname(filePath).toLowerCase();
  return EXT_MAP.get(ext) ?? null;
}

/**
 * Resolve the binary path for a linter.
 * Bundled linters: check project node_modules/.bin first, then PATH.
 * System linters: check PATH only.
 * Returns null if binary not found.
 */
function resolveBinary(config: LinterConfig, projectRoot: string): null | string {
  if (config.source === "bundled") {
    // 1. Project-local node_modules
    const localBin = path.join(projectRoot, "node_modules", ".bin", config.binaryName);
    if (fs.existsSync(localBin)) return localBin;

    // 2. PATH (covers global npm install of aiwcli)
    return findExecutable(config.binaryName);
  }

  // System linters: PATH only
  return findExecutable(config.binaryName);
}

/**
 * Run a linter on a file.
 * Returns null if the linter binary is not found.
 * Returns { errors: [] } if the file passes lint.
 */
export function runLinter(
  config: LinterConfig,
  filePath: string,
  projectRoot: string,
): null | { errors: LintError[] } {
  const binary = resolveBinary(config, projectRoot);
  if (!binary) {
    logDebug("lint-dispatch", `${config.name} binary not found, skipping`);
    return null;
  }

  const args = config.buildArgs(filePath);

  try {
    const result = spawnSync(binary, args, {
      cwd: projectRoot,
      timeout: 8000, // 8s soft limit (10s hook timeout is the hard kill)
      stdio: 'pipe',
      encoding: 'utf8',
    });

    const exitCode = result.status ?? 1;
    const stdout = result.stdout ?? "";
    const stderr = result.stderr ?? "";

    // Exit 0 = clean
    if (exitCode === 0) return { errors: [] };

    // Known lint-error exit codes → parse output
    if (config.lintExitCodes.includes(exitCode)) {
      const errors = config.parseOutput(stdout, stderr, exitCode);
      return { errors };
    }

    // Unknown exit code = crash/timeout → skip
    logWarn("lint-dispatch", `${config.name} exited with unexpected code ${exitCode} on ${filePath}`);
    return { errors: [] };
  } catch (error) {
    logWarn("lint-dispatch", `${config.name} execution failed: ${error}`);
    return { errors: [] };
  }
}

/**
 * Format lint errors for Claude's context injection.
 * Returns a human-readable string suitable for emitContext().
 */
export function formatLintErrors(
  filePath: string,
  linterName: string,
  errors: LintError[],
  maxShown = 15,
): string {
  const shown = errors.slice(0, maxShown);
  const lines = [
    `Lint: ${errors.length} issue(s) in \`${filePath}\` (${linterName})`,
    "",
  ];

  for (const err of shown) {
    const loc = err.column ? `L${err.line}:${err.column}` : `L${err.line}`;
    const sev = err.severity === "error" ? "error" : "warn";
    const rule = err.rule ? ` [${err.rule}]` : "";
    lines.push(`- **${sev}** ${loc}: ${err.message}${rule}`);
  }

  if (errors.length > maxShown) {
    lines.push(`- ... and ${errors.length - maxShown} more`);
  }

  lines.push("", "Fix these lint errors in the file you just edited.");

  return lines.join("\n");
}

/**
 * Unified logging for all hooks and libraries.
 *
 * Log format: JSONL (one JSON object per line)
 * Log location: _output/hook-log.jsonl (global, all sessions)
 * Filter by session using the "sid" field.
 *
 * stderr is OPT-IN: convenience functions (logDebug, logInfo, logWarn, logError)
 * write to file only by default. To also write to stderr (visible to Claude Code
 * as "hook error"), pass { stderr: true } or use logBlocking().
 * logHookError() always writes to stderr (unhandled errors must be visible).
 *
 * Environment variables:
 * - HOOK_LOG_DISABLE=1: Disable all file logging
 * - HOOK_LOG_LEVEL=warn: Minimum level to log (default: debug)
 * - HOOK_ERROR_LOG_DISABLE=1: Legacy alias for HOOK_LOG_DISABLE
 *
 * Never throws. No buffering. Stdlib only.
 * See SPEC.md §3
 */

import * as fs from "node:fs";
import * as path from "node:path";

const LEVELS: Record<string, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const MAX_LOG_LINES = 10_000; // Max lines in global log before pruning

// Module-level session ID cache
let _cachedSessionId: null | string = null;

// Module-level context path cache (kept for external callers)
let _cachedContextPath: null | string = null;
let _contextResolved = false;

/**
 * Set the session ID for this process. All subsequent log calls include it.
 */
export function setSessionId(sessionId: null | string): void {
  _cachedSessionId = sessionId;
}

/**
 * Set the context path for this process. Kept for external callers.
 */
export function setContextPath(contextPath: null | string): void {
  _cachedContextPath = contextPath;
  _contextResolved = true;
}

export function getContextPath(): null | string {
  if (!_contextResolved) {
    _contextResolved = true; // Don't retry
  }

  return _cachedContextPath;
}

function getMinLevel(): number {
  const env = (process.env.HOOK_LOG_LEVEL ?? "debug").toLowerCase();
  return LEVELS[env] ?? 0;
}

function isDisabled(): boolean {
  return (
    process.env.HOOK_LOG_DISABLE === "1" ||
    process.env.HOOK_ERROR_LOG_DISABLE === "1" ||
    process.env.CCNATIVE_DEBUG_DISABLE === "1"
  );
}

function getProjectRoot(): string {
  return process.env.CLAUDE_PROJECT_DIR || process.cwd();
}

/**
 * Write a structured log entry to the global hook log.
 *
 * All entries go to _output/hook-log.jsonl. Use the "sid" field
 * (set via setSessionId) to filter by session.
 */
export function hookLog(
  level: string,
  hookName: string,
  message: string,
  opts?: {
    component?: string;
    data?: any;
    stderr?: boolean;
    traceback_str?: string;
  },
): void {
  try {
    const levelLower = level.toLowerCase();
    const levelNum = LEVELS[levelLower] ?? 0;
    const component = opts?.component ?? "";
    const tracebackStr = opts?.traceback_str ?? "";
    const stderrEnabled = opts?.stderr === true;

    // Write to stderr
    if (stderrEnabled) {
      const prefix = component
        ? `[${hookName}:${component}]`
        : `[${hookName}]`;
      process.stderr.write(`${prefix} ${message}\n`);
      if (tracebackStr) {
        process.stderr.write(tracebackStr + "\n");
      }
    }

    // Check if file logging is enabled
    if (isDisabled()) return;

    // Check minimum level
    if (levelNum < getMinLevel()) return;

    // Build JSONL entry
    const now = new Date();
    const ts = now.toISOString().replace("Z", "").slice(0, 23);
    const entry: Record<string, any> = {
      ts,
      level: levelLower,
      hook: hookName,
      msg: message,
    };
    if (_cachedSessionId) entry.sid = _cachedSessionId;
    if (component) entry.component = component;
    if (opts?.data !== undefined && opts.data !== null) {
      try {
        JSON.stringify(opts.data);
        entry.data = opts.data;
      } catch {
        entry.data = String(opts.data);
      }
    }

    if (tracebackStr) entry.tb = tracebackStr.trimEnd();

    const line = JSON.stringify(entry) + "\n";

    // Always write to global log
    const logPath = path.join(getProjectRoot(), "_output", "hook-log.jsonl");

    // Ensure directory exists
    const dir = path.dirname(logPath);
    fs.mkdirSync(dir, { recursive: true });

    // Line-count guard: prune to last MAX_LOG_LINES
    try {
      if (fs.existsSync(logPath)) {
        const content = fs.readFileSync(logPath, "utf8");
        const lines = content.split(/\r?\n/);
        if (lines.length > MAX_LOG_LINES) {
          fs.writeFileSync(
            logPath,
            lines.slice(lines.length - MAX_LOG_LINES).join("\n"),
            "utf-8",
          );
        }
      }
    } catch {
      // ignore
    }

    fs.appendFileSync(logPath, line, "utf-8");
  } catch {
    // Never crash
  }
}

export function logDebug(hookName: string, message: string, opts?: Record<string, any>): void {
  hookLog("debug", hookName, message, opts);
}

export function logInfo(hookName: string, message: string, opts?: Record<string, any>): void {
  hookLog("info", hookName, message, opts);
}

export function logWarn(hookName: string, message: string, opts?: Record<string, any>): void {
  hookLog("warn", hookName, message, opts);
}

export function logError(hookName: string, message: string, opts?: Record<string, any>): void {
  hookLog("error", hookName, message, opts);
}

/**
 * Log an error that SHOULD be visible to user/model via stderr.
 * Use for real problems needing attention, not routine diagnostics.
 */
export function logBlocking(hookName: string, message: string, opts?: Record<string, any>): void {
  hookLog("error", hookName, message, { ...opts, stderr: true });
}

/**
 * Log a structured diagnostic entry at a hook decision point.
 * See SPEC.md §3.8
 */
export function logDiagnostic(
  hookName: string,
  phase: string,
  summary: string,
  opts?: {
    component?: string;
    data?: any;
    decision?: any;
    inputs?: any;
    reasoning?: any;
  },
): void {
  const diagData: Record<string, any> = { phase };
  if (opts?.inputs !== undefined) diagData.inputs = opts.inputs;
  if (opts?.decision !== undefined) diagData.decision = opts.decision;
  if (opts?.reasoning !== undefined) diagData.reasoning = opts.reasoning;
  if (opts?.data && typeof opts.data === "object") {
    Object.assign(diagData, opts.data);
  }

  hookLog("debug", hookName, `[DIAG:${phase}] ${summary}`, {
    component: opts?.component ?? "diag",
    data: diagData,
  });
}

/**
 * Backward-compatible wrapper matching old hook_utils.log_hook_error signature.
 * See SPEC.md §3.6
 */
export function logHookError(
  hookName: string,
  error: Error | string,
  hookEvent = "unknown",
  tracebackStr = "",
): void {
  const errStr = typeof error === "string" ? error : String(error);
  const msg = errStr.replaceAll(/[\n\r]/g, " ").slice(0, 200);
  const errType =
    typeof error === "object" && error !== null
      ? error.constructor.name
      : "Error";
  hookLog("error", hookName, `[${hookEvent}] ${errType}: ${msg}`, {
    traceback_str: tracebackStr,
    stderr: true,
  });
}

/**
 * Shared preflight health check for provider+model availability.
 * Extracted from plan-review/lib/preflight.ts for reuse by any hook.
 *
 * Validates that a CLI tool + model combo works by running a minimal "ping" request.
 */

import { logDebug, logWarn } from "./logger.js";
import { execFileAsync, findExecutable, getInternalSubprocessEnv } from "./subprocess-utils.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface PreflightCommandConfig {
  buildArgs: (model: string) => string[];
  cliName: string;
  input: string;
}

export interface PreflightCheckResult {
  available: boolean;
  error?: string;
  latencyMs: number;
  model: string;
  provider: string;
}

// ---------------------------------------------------------------------------
// Error Classification
// ---------------------------------------------------------------------------

export function classifyError(
  stderr: string,
  exitCode: null | number,
  killed: boolean,
  signal: null | string,
): string {
  if (killed || signal === "SIGTERM") return "Preflight timed out";
  if (/model.*not found|not available/i.test(stderr)) return "Model not available for this account";
  if (/rate limit|429/i.test(stderr)) return "Rate limited";
  if (/auth|api key|401/i.test(stderr)) return "Authentication failed";
  if (/quota|billing/i.test(stderr)) return "Quota/billing issue";
  return `Exit code ${exitCode}`;
}

// ---------------------------------------------------------------------------
// Single Provider+Model Check
// ---------------------------------------------------------------------------

/**
 * Check if a single provider:model combo is available.
 * Takes a PreflightCommandConfig so callers define their own CLI args.
 */
export async function checkProviderModel(
  provider: string,
  model: string,
  config: PreflightCommandConfig,
  timeoutMs: number,
  hook = "preflight",
): Promise<PreflightCheckResult> {
  const cliPath = findExecutable(config.cliName);
  if (!cliPath) {
    return { provider, model, available: false, latencyMs: 0, error: `CLI '${config.cliName}' not found on PATH` };
  }

  const start = Date.now();
  try {
    const env = getInternalSubprocessEnv();
    const result = await execFileAsync(cliPath, config.buildArgs(model), {
      input: config.input,
      timeout: timeoutMs,
      env: env as Record<string, string>,
      maxBuffer: 1 * 1024 * 1024,
      shell: process.platform === "win32",
    });

    const latencyMs = Date.now() - start;

    if (result.killed || result.signal === "SIGTERM") {
      return { provider, model, available: false, latencyMs, error: "Preflight timed out" };
    }

    if (result.exitCode !== 0) {
      const error = classifyError(result.stderr, result.exitCode, result.killed, result.signal);
      logWarn(hook, `${provider}:${model} failed: ${error} (stderr: ${result.stderr.slice(-200)})`);
      return { provider, model, available: false, latencyMs, error };
    }

    logDebug(hook, `${provider}:${model} passed (${latencyMs}ms)`);
    return { provider, model, available: true, latencyMs };
  } catch (error_) {
    const latencyMs = Date.now() - start;
    const error = error_ instanceof Error ? error_.message : String(error_);
    logWarn(hook, `${provider}:${model} exception: ${error}`);
    return { provider, model, available: false, latencyMs, error };
  }
}

import * as fs from 'node:fs'
import * as os from 'node:os'
import * as path from 'node:path'

export interface SentinelIpcPaths {
  inputPath: string
  sentinelPath: string
  stderrPath: string
  stdoutPath: string
  tmpDir: string
}

function sanitizePrefix(prefix: string): string {
  return prefix.replaceAll(/[^a-zA-Z0-9_-]/g, '-')
}

export function createSentinelIpcPaths(prefix: string): SentinelIpcPaths {
  const safePrefix = sanitizePrefix(prefix)
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), `${safePrefix}-`))

  return {
    tmpDir,
    inputPath: path.join(tmpDir, 'input.txt'),
    stdoutPath: path.join(tmpDir, 'stdout.txt'),
    stderrPath: path.join(tmpDir, 'stderr.txt'),
    sentinelPath: path.join(tmpDir, 'sentinel.txt'),
  }
}

export function buildShellCaptureScript(
  command: string,
  paths: Pick<SentinelIpcPaths, 'inputPath' | 'sentinelPath' | 'stderrPath' | 'stdoutPath'>,
  quote: (input: string) => string,
): string {
  return [
    command,
    `< ${quote(paths.inputPath)}`,
    `> ${quote(paths.stdoutPath)}`,
    `2> ${quote(paths.stderrPath)}`,
    `; echo $? > ${quote(paths.sentinelPath)}`,
  ].join(' ')
}

export async function waitForSentinelFile(
  sentinelPath: string,
  timeoutMs: number,
  pollIntervalMs = 250,
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    if (fs.existsSync(sentinelPath)) return true
    await new Promise<void>((resolve) => {
      setTimeout(resolve, pollIntervalMs)
    })
  }

  return fs.existsSync(sentinelPath)
}

export function readSentinelExitCode(sentinelPath: string, fallback = 1): number {
  if (!fs.existsSync(sentinelPath)) return fallback

  const raw = fs.readFileSync(sentinelPath, 'utf8').trim()
  const parsed = Number.parseInt(raw, 10)
  return Number.isFinite(parsed) ? parsed : fallback
}

export function readTextIfExists(filePath: string): string {
  if (!filePath || !fs.existsSync(filePath)) return ''
  return fs.readFileSync(filePath, 'utf8')
}

export function cleanupSentinelIpc(paths: Pick<SentinelIpcPaths, 'tmpDir'>): void {
  try {
    fs.rmSync(paths.tmpDir, { recursive: true, force: true })
  } catch {
    // Best-effort cleanup.
  }
}

export function cleanupSentinelPath(sentinelPath: string | undefined): void {
  if (!sentinelPath) return

  try {
    fs.rmSync(path.dirname(sentinelPath), { recursive: true, force: true })
  } catch {
    // Best-effort cleanup.
  }
}

/**
 * Shared I/O for state.json — read, write, serialize.
 * Extracted to avoid circular deps between context-store and task-tracker.
 * See SPEC.md §7.1
 */

import * as fs from "node:fs";
import * as path from "node:path";

import { atomicWrite } from "./atomic-write.js";
import { getContextDir } from "./constants.js";
import { logWarn } from "./logger.js";
import type { ContextState, Mode } from "../types.js";

/** Mode migration from legacy context_manager values. */
const MODE_MIGRATION: Record<string, Mode> = {
  none: "idle",
  planning: "idle",
  pending_implementation: "has_staged_work",
  implementing: "active",
};

/** Legacy state data structure for migration type safety. */
interface LegacyStateData {
  handoff_consumed?: boolean;
  handoff_path?: null | string;
  mode?: string;
  next_artifact_type?: "handoff" | "plan" | null;
  plan_consumed?: boolean;
  plan_hash?: null | string;
  plan_path?: null | string;
  work_consumed?: boolean;
}

/**
 * Serialize a ContextState for JSON output.
 * Omits null/undefined keys but keeps false, 0, empty string, and empty arrays.
 */
export function toDict(state: ContextState): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(state)) {
    if (value !== null && value !== undefined) {
      result[key] = value;
    }
  }

  return result;
}

/**
 * Migrate old consumed flags to unified work_consumed.
 * Runs on every state.json read for transparent backward compatibility.
 * Idempotent: safe to run multiple times.
 */
function migrateConsumedFlags(data: Record<string, unknown>): void {
  const legacy = data as LegacyStateData;

  // Skip if already migrated (check both fields and mode)
  const alreadyMigrated =
    typeof legacy.work_consumed === "boolean" &&
    legacy.mode !== "has_plan" &&
    legacy.mode !== "has_handoff";
  if (alreadyMigrated) return;

  const hasPlan = Boolean(legacy.plan_path && legacy.plan_hash);
  const hasHandoff = Boolean(legacy.handoff_path);

  // Migrate consumed flag (plan takes precedence if both exist)
  if (hasPlan && typeof legacy.plan_consumed === "boolean") {
    (data as Record<string, unknown>).work_consumed = legacy.plan_consumed;
  } else if (hasHandoff && typeof legacy.handoff_consumed === "boolean") {
    (data as Record<string, unknown>).work_consumed = legacy.handoff_consumed;
  } else {
    (data as Record<string, unknown>).work_consumed = false;
  }

  // Migrate mode: has_plan/has_handoff → has_staged_work
  if (legacy.mode === "has_plan" || legacy.mode === "has_handoff") {
    const artifactType = legacy.mode === "has_handoff" ? "handoff" : "plan";
    (data as Record<string, unknown>).mode = "has_staged_work";
    (data as Record<string, unknown>).next_artifact_type = artifactType;
  }

  // Set next_artifact_type based on which artifact exists
  if (!legacy.next_artifact_type) {
    if (hasPlan && hasHandoff) {
      // Both exist - conflict resolution: plan priority during migration
      // (Cannot determine "latest" without timestamps - plan takes precedence)
      (data as Record<string, unknown>).next_artifact_type = "plan";
      (data as Record<string, unknown>).handoff_path = null;
    } else if (hasPlan) {
      (data as Record<string, unknown>).next_artifact_type = "plan";
    } else if (hasHandoff) {
      (data as Record<string, unknown>).next_artifact_type = "handoff";
    }
  }

  // Delete old flags (clean cut migration)
  delete (data as Record<string, unknown>).plan_consumed;
  delete (data as Record<string, unknown>).handoff_consumed;
}

/**
 * Get path to state.json for a context.
 */
export function statePath(contextId: string, projectRoot?: string): string {
  return path.join(getContextDir(contextId, projectRoot), "state.json");
}

/**
 * Read and parse state.json for a context.
 * Applies legacy mode migration. Returns null if file doesn't exist or is corrupt.
 */
export function readStateJson(
  contextId: string,
  projectRoot?: string,
): ContextState | null {
  const sp = statePath(contextId, projectRoot);
  if (!fs.existsSync(sp)) return null;

  try {
    const raw = fs.readFileSync(sp, "utf8");
    const data = JSON.parse(raw) as Record<string, any>;
    migrateConsumedFlags(data); // Migrate before dictToState
    return dictToState(data);
  } catch (error: any) {
    logWarn("state_io", `Failed to read state.json for '${contextId}': ${error}`);
    return null;
  }
}

/**
 * Atomically write state.json for a context.
 * Returns [success, error].
 */
export function writeStateJson(
  contextId: string,
  state: ContextState,
  projectRoot?: string,
): [boolean, null | string] {
  const sp = statePath(contextId, projectRoot);
  const dir = path.dirname(sp);
  fs.mkdirSync(dir, { recursive: true });

  const content = JSON.stringify(toDict(state), null, 2);
  return atomicWrite(sp, content);
}

/**
 * Construct a ContextState from a dict, migrating old mode names.
 * Only includes fields that are present in the source data (preserves null-stripping).
 */
export function dictToState(data: Record<string, unknown>): ContextState {
  // Validate required fields
  if (typeof data.id !== "string" || !data.id) {
    throw new Error("dictToState: missing or invalid required field 'id'");
  }

  const rawMode: string =
    typeof data.mode === "string" ? data.mode : "idle";
  const mode: Mode = (MODE_MIGRATION[rawMode] ?? rawMode) as Mode;

  const state: any = {
    id: data.id,
    status: data.status ?? "active",
    summary: data.summary ?? "",
    method: data.method ?? "",
    tags: data.tags ?? [],
    created_at: data.created_at ?? "",
    last_active: data.last_active ?? "",
    mode,
    plan_anchors: data.plan_anchors ?? [],
    work_consumed: data.work_consumed ?? false,
    session_ids: data.session_ids ?? [],
    tasks: data.tasks ?? [],
  };

  // Only set nullable fields if they exist in the source data
  if ("plan_path" in data) state.plan_path = data.plan_path;
  if ("plan_hash" in data) state.plan_hash = data.plan_hash;
  if ("plan_signature" in data) state.plan_signature = data.plan_signature;
  if ("plan_id" in data) state.plan_id = data.plan_id;
  if ("handoff_path" in data) state.handoff_path = data.handoff_path;
  if ("next_artifact_type" in data) state.next_artifact_type = data.next_artifact_type;
  if ("last_session" in data) state.last_session = data.last_session;

  // Migration: plan_hash_consumed (added in multi-plan context fix)
  if ("plan_hash_consumed" in data) {
    state.plan_hash_consumed = data.plan_hash_consumed;
  } else {
    state.plan_hash_consumed = null;  // Default for old contexts
  }

  // Preserve method-specific extension data (e.g., cc_native) that isn't
  // part of the core ContextState interface. Without this, round-trip
  // read→write cycles silently drop extension fields.
  for (const key of Object.keys(data)) {
    if (!(key in state)) {
      state[key] = data[key];
    }
  }

  return state as ContextState;
}

import { execFile } from 'node:child_process'
import type { ChildProcess } from 'node:child_process'

import { resolveExecutable } from './executable-policy.js'

const childProcesses = new Set<ChildProcess>()

function cleanupChildren(): void {
  for (const child of childProcesses) {
    try {
      child.kill('SIGKILL')
    } catch {
      // Child may have already exited.
    }
  }

  childProcesses.clear()
}

process.on('exit', () => {
  cleanupChildren()
})

process.on('SIGINT', () => {
  cleanupChildren()
  process.exit(130)
})

process.on('SIGTERM', () => {
  cleanupChildren()
  process.exit(143)
})

export function isInternalCall(): boolean {
  return process.env.AIWCLI_INTERNAL_CALL === 'true'
}

export function getInternalSubprocessEnv(): Record<string, string | undefined> {
  const env: Record<string, string | undefined> = {
    ...process.env,
    AIWCLI_INTERNAL_CALL: 'true',
  }

  delete env.CLAUDECODE
  delete env.CLAUDE_CODE_ENTRYPOINT
  return env
}

export function findExecutable(name: string): null | string {
  return resolveExecutable(name, { windowsProfile: 'cmdOrExeFirst' })
}

export interface ExecSyncError {
  killed: boolean
  message: string
  signal: null | string
  status: null | number
  stderr: Buffer | string
  stdout: Buffer | string
}

export function isExecSyncError(error: unknown): error is ExecSyncError {
  return typeof error === 'object' && error !== null && 'killed' in error && 'signal' in error
}

export function normalizePathForCli(pathValue: string): string {
  if (process.platform !== 'win32') return pathValue
  return pathValue.replaceAll('\\', '/')
}

export function shellQuoteWin(arg: string): string {
  if (process.platform !== 'win32') return arg
  return '"' + arg.replaceAll('"', '""') + '"'
}

export interface ExecResult {
  exitCode: number
  killed: boolean
  signal: null | string
  stderr: string
  stdout: string
}

export interface ExecAsyncOptions {
  env?: Record<string, string | undefined> | undefined
  input?: string | undefined
  maxBuffer?: number | undefined
  shell?: boolean | undefined
  timeout?: number | undefined
}

export function execFileAsync(
  file: string,
  args: string[],
  options?: ExecAsyncOptions,
): Promise<ExecResult> {
  return new Promise((resolve) => {
    const child = execFile(
      file,
      args,
      {
        encoding: 'utf-8',
        timeout: options?.timeout ?? 0,
        env: options?.env as NodeJS.ProcessEnv,
        maxBuffer: options?.maxBuffer ?? 10 * 1024 * 1024,
        shell: options?.shell,
      },
      (error, stdout, stderr) => {
        if (error) {
          const errObj = error as unknown as Record<string, unknown>
          resolve({
            stdout: String(stdout ?? ''),
            stderr: String(stderr ?? ''),
            exitCode: typeof errObj.code === 'number' ? errObj.code : (error as any).status ?? 1,
            killed: Boolean(errObj.killed),
            signal: typeof errObj.signal === 'string' ? errObj.signal : null,
          })
        } else {
          resolve({
            stdout: String(stdout ?? ''),
            stderr: String(stderr ?? ''),
            exitCode: 0,
            killed: false,
            signal: null,
          })
        }
      },
    )

    childProcesses.add(child)
    child.on('exit', () => {
      childProcesses.delete(child)
    })

    if (options?.input !== null && options?.input !== undefined && child.stdin) {
      child.stdin.write(options.input)
      child.stdin.end()
    }
  })
}

/**
 * Core utilities for shared context management.
 * See SPEC.md §14.2, §14.3
 */

import { sanitizeTitle } from "./constants.js";
import { logDebug, logError, logWarn } from "./logger.js";
import { STOP_WORDS } from "./stop-words.js";

/**
 * Print to stderr. For terminal-only UX messages, not diagnostics.
 */
export function eprint(...args: any[]): void {
  process.stderr.write(args.map(String).join(" ") + "\n");
}

/**
 * Get current local datetime as Date.
 */
export function nowLocal(): Date {
  return new Date();
}

/**
 * Get current time as ISO 8601 string (local time, no timezone suffix).
 * Matches Python datetime.now().isoformat() behavior.
 */
export function nowIso(): string {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hours = String(d.getHours()).padStart(2, "0");
  const minutes = String(d.getMinutes()).padStart(2, "0");
  const seconds = String(d.getSeconds()).padStart(2, "0");
  const ms = String(d.getMilliseconds()).padStart(3, "0");
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${ms}`;
}

/**
 * Format datetime for display.
 * Returns "YYYY-MM-DD HH:MM:SS"
 * See SPEC.md §14.3
 */
export function formatTimestamp(dt?: Date): string {
  const d = dt ?? nowLocal();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hours = String(d.getHours()).padStart(2, "0");
  const minutes = String(d.getMinutes()).padStart(2, "0");
  const seconds = String(d.getSeconds()).padStart(2, "0");
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * Parse ISO 8601 timestamp string.
 * Returns null if parsing fails.
 * See SPEC.md §14.3
 */
export function parseIsoTimestamp(isoStr: string): Date | null {
  try {
    const normalized = isoStr.replace("Z", "+00:00");
    const d = new Date(normalized);
    if (isNaN(d.getTime())) return null;
    return d;
  } catch {
    return null;
  }
}

/**
 * Normalize a filesystem path for display — always uses forward slashes.
 * No-op on Unix; converts backslashes on Windows.
 */
export function displayPath(p: string): string {
  return p.replaceAll("\\", "/");
}

/**
 * Clean text for stop-word matching in slug generation.
 * Strips apostrophes (i'm -> im), removes punctuation, normalizes whitespace.
 * See SPEC.md §14.2
 */
export function cleanTextForSlug(text: string): string {
  if (!text) return "";
  let result = text.toLowerCase();
  result = result.replaceAll('\'', "");            // i'm -> im, you're -> youre
  result = result.replaceAll(/[^a-z0-9\s]/g, " "); // punctuation -> spaces
  result = result.replaceAll(/\s+/g, " ").trim();
  return result;
}

/**
 * Generate a slug from text using AI inference with stop-word fallbacks.
 * Pipeline: AI inference → stop-word post-filter → stop-word fallback → word-length fallback.
 * Reusable by both context ID generation and plan archival.
 * See SPEC.md §14.2
 */
export function generateSlug(
  text: string,
  maxLen = 150,
  fallbackSlug = "context",
): string {
  if (!text || !text.trim()) return fallbackSlug;

  let slug: null | string = null;
  const cleanedText = cleanTextForSlug(text);

  // Tier 1: AI inference via generateContextIdSlug (sync — uses execFileSync)
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports, no-undef
    const { generateContextIdSlug } = require("./inference.js");
    const aiSlug = generateContextIdSlug(text);
    if (aiSlug) {
      const filteredWords = aiSlug
        .split(/\s+/)
        .filter(
          (w: string) => !STOP_WORDS.has(w.toLowerCase()) && w.length > 1,
        );
      if (filteredWords.length >= 5) {
        slug = sanitizeTitle(filteredWords.join(" "), maxLen);
      } else {
        logDebug(
          "utils",
          `AI slug too generic after stop-word filter (${filteredWords.length} words remain), using fallback`,
        );
      }
    }
  } catch (error: any) {
    logWarn("utils", `AI slug generation failed, using fallback: ${error}`);
  }

  // Tier 2: Stop-word filtering on cleaned text
  if (!slug) {
    const words = cleanedText
      .split(/\s+/)
      .filter((w) => !STOP_WORDS.has(w) && w.length > 1)
      .slice(0, 12);
    slug = words.length >= 3
      ? sanitizeTitle(words.join(" "), maxLen)
      : sanitizeTitle(
          cleanedText.split(/\s+/).filter((w) => w.length > 2).slice(0, 6).join(" "),
          maxLen,
        ) || fallbackSlug;
  }

  return slug;
}

/**
 * Generate a context ID from a summary string.
 * Format: YYMMDD-HHMM-slug
 * Delegates slug generation to generateSlug().
 * See SPEC.md §14.2
 */
export function generateContextId(
  summary: string,
  existingIds?: Set<string>,
): string {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(2);
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");
  const hh = String(now.getHours()).padStart(2, "0");
  const min = String(now.getMinutes()).padStart(2, "0");
  const timestamp = `${yy}${mm}${dd}-${hh}${min}`;

  let baseId: string;

  try {
    const slug = generateSlug(summary);
    baseId = `${timestamp}-${slug}`;
  } catch (error: any) {
    logError(
      "utils",
      `Context ID generation failed entirely, using timestamp: ${error}`,
    );
    baseId = `${timestamp}-context`;
  }

  if (!existingIds || !existingIds.has(baseId)) {
    return baseId;
  }

  let counter = 2;
  while (existingIds.has(`${baseId}-${counter}`)) {
    counter++;
  }

  return `${baseId}-${counter}`;
}

import {promises as fs} from 'node:fs'
import {dirname, join} from 'node:path'

import {IdePathResolver} from './ide-path-resolver.js'
import {pathExists} from './paths.js'

/**
 * Configuration for template installation
 */
interface TemplateInstallConfig {
  /** List of IDE names to install (e.g., ['claude', 'windsurf']) */
  ides: string[]
  /** Project name for configuration generation */
  projectName: string
  /** Target directory where template will be installed */
  targetDir: string
  /** Name of the template to install (e.g., 'bmad') */
  templateName: string
  /** Absolute path to the template directory */
  templatePath: string
  /** Username for configuration generation */
  username: string
}

/**
 * Status of a single template item (file or folder)
 */
interface TemplateItemStatus {
  /** Whether the item exists in target directory */
  exists: boolean
  /** Whether the item is a directory */
  isDirectory: boolean
  /** The item name */
  name: string
}

/**
 * Result of checking template installation status
 */
interface TemplateInstallationStatus {
  /** Items that already exist in target directory */
  existing: TemplateItemStatus[]
  /** Items that are missing from target directory */
  missing: TemplateItemStatus[]
  /** The method-specific workflow folder name (e.g., '_gsd', '_bmad') */
  workflowFolder: null | string
  /** Whether the workflow folder exists */
  workflowFolderExists: boolean
}

/**
 * Result of template installation
 */
interface InstallationResult {
  /** List of folder names that were installed (for gitignore) */
  installedFolders: string[]
  /** Whether shared settings were merged into IDE settings */
  sharedSettingsMerged: boolean
  /** Absolute path to the template that was installed */
  templatePath: string
}

/**
 * Check template installation status for a method.
 * Returns which items exist and which are missing.
 *
 * @param templatePath - Path to the template directory
 * @param targetDir - Target directory to check
 * @param ides - List of IDEs to check (for dot folders)
 * @param templateName - Name of the template (for identifying workflow folder)
 * @returns Status of template items
 */
export async function checkTemplateStatus(
  templatePath: string,
  targetDir: string,
  ides: string[],
  templateName: string,
): Promise<TemplateInstallationStatus> {
  const existing: TemplateItemStatus[] = []
  const missing: TemplateItemStatus[] = []

  // Scan template directory
  const entries = await fs.readdir(templatePath, {withFileTypes: true})

  // Identify workflow folder based on template name
  // Convention: _templatename (e.g., _gsd, _bmad)
  const workflowFolderName = `_${templateName}`
  let workflowFolder: null | string = null
  let workflowFolderExists = false

  // Filter entries to only include relevant items (skip non-selected IDE folders and excluded patterns)
  const relevantEntries = entries.filter((entry) => {
    // Skip excluded patterns (test files, cache, etc.)
    if (shouldExclude(entry.name)) {
      return false
    }

    if (entry.name.startsWith('.') && entry.isDirectory()) {
      const ideName = entry.name.slice(1)
      return ides.includes(ideName)
    }

    return true
  })

  // Check all entries in parallel
  // Non-dot folders go into .aiwcli/, dot folders stay at project root
  const resolver = new IdePathResolver(targetDir)
  const containerDir = resolver.getAiwcliContainer()
  const statusChecks = relevantEntries.map(async (entry) => {
    // Dot folders (IDE folders) are at project root, non-dot folders are in .aiwcli/
    const targetPath = entry.name.startsWith('.')
      ? resolver.getIdeDir(entry.name.slice(1))
      : join(containerDir, entry.name)
    const exists = await pathExists(targetPath)
    return {
      name: entry.name,
      isDirectory: entry.isDirectory(),
      exists,
    }
  })

  const statuses = await Promise.all(statusChecks)

  for (const status of statuses) {
    if (status.exists) {
      existing.push(status)
    } else {
      missing.push(status)
    }

    // Track workflow folder
    if (status.name === workflowFolderName) {
      workflowFolder = workflowFolderName
      workflowFolderExists = status.exists
    }
  }

  return {
    existing,
    missing,
    workflowFolder,
    workflowFolderExists,
  }
}

/**
 * Patterns to exclude when copying template directories.
 * These are development/test artifacts that shouldn't be packaged.
 */
const EXCLUDED_PATTERNS = new Set([
  '_output',
])

/**
 * Check if a filename should be excluded from copying
 */
export function shouldExclude(name: string): boolean {
  return EXCLUDED_PATTERNS.has(name)
}

/**
 * Copy directory recursively with proper error handling.
 * Excludes test files, cache directories, and output folders.
 *
 * @param src - Source directory path
 * @param dest - Destination directory path
 * @param excludeIdeFolders - If true, exclude IDE config folders (.claude, .windsurf, etc.)
 */
export async function copyDir(src: string, dest: string, excludeIdeFolders: boolean = false): Promise<void> {
  await fs.mkdir(dest, {recursive: true})

  const entries = await fs.readdir(src, {withFileTypes: true})

  const operations = entries
    .filter((entry) => {
      // Standard exclusions (test files, cache, etc.)
      if (shouldExclude(entry.name)) {
        return false
      }

      // Exclude IDE config folders if requested (used for _shared folder)
      // These folders are used for settings merging, not direct installation
      if (excludeIdeFolders && entry.isDirectory() && entry.name.startsWith('.')) {
        return false
      }

      return true
    })
    .map(async (entry) => {
      const srcPath = join(src, entry.name)
      const destPath = join(dest, entry.name)

      try {
        return entry.isDirectory() ? await copyDir(srcPath, destPath, excludeIdeFolders) : await fs.copyFile(srcPath, destPath)
      } catch (error) {
        const err = error as Error
        throw new Error(`Failed to copy ${srcPath} to ${destPath}: ${err.message}`)
      }
    })

  await Promise.all(operations)
}

/**
 * Merge source directory into destination, skipping existing files.
 * Unlike copyDir, this preserves existing files in destination.
 *
 * @param src - Source directory path
 * @param dest - Destination directory path
 */
async function mergeDirectory(src: string, dest: string): Promise<void> {
  await fs.mkdir(dest, {recursive: true})
  const entries = await fs.readdir(src, {withFileTypes: true})

  const ops = entries
    .filter((entry) => !shouldExclude(entry.name))
    .map(async (entry) => {
      const srcPath = join(src, entry.name)
      const destPath = join(dest, entry.name)

      if (entry.isDirectory()) {
        await mergeDirectory(srcPath, destPath)
      } else if (!(await pathExists(destPath))) {
        await fs.copyFile(srcPath, destPath)
      }
    })
  await Promise.all(ops)
}

/**
 * Install template with IDE-specific folder selection.
 *
 * Template structure:
 * - Non-dot folders (e.g., _bmad/, GSR/) → .aiwcli/ (always overwritten)
 * - _shared/ → .aiwcli/_shared/ (always overwritten)
 * - IDE dot folders (e.g., .claude/) → decomposed into method-owned subdirs
 *
 * Settings reconstruction is handled separately by the caller via reconstructIdeSettings().
 *
 * @param config - Installation configuration
 * @returns Installation result with list of installed folders
 * @throws Error if template doesn't exist or requested IDE folder not found
 */
export async function installTemplate(
  config: TemplateInstallConfig,
): Promise<InstallationResult> {
  const {templateName, targetDir, ides, templatePath} = config

  // Verify template exists
  try {
    await fs.access(templatePath)
  } catch {
    throw new Error(
      `Template '${templateName}' not found at ${templatePath}. ` +
        `This indicates a corrupted installation. Please reinstall aiwcli.`,
    )
  }

  // Scan template directory to classify folders (excluding test/cache patterns)
  const entries = await fs.readdir(templatePath, {withFileTypes: true})
  const directories = entries.filter((entry) => entry.isDirectory() && !shouldExclude(entry.name))

  const nonDotFolders: string[] = []
  const dotFolders: Map<string, string> = new Map() // ide name -> folder name

  for (const dir of directories) {
    if (dir.name.startsWith('.')) {
      // Extract IDE name from dot folder (e.g., '.claude' -> 'claude')
      const ideName = dir.name.slice(1)
      dotFolders.set(ideName, dir.name)
    } else {
      nonDotFolders.push(dir.name)
    }
  }

  // Validate requested IDE folders exist in template
  const availableIdes = [...dotFolders.keys()]
  const missingIdes = ides.filter((ide) => !dotFolders.has(ide))

  if (missingIdes.length > 0) {
    throw new Error(
      `IDE '${missingIdes[0]}' not available for template '${templateName}'. ` +
        `Available: ${availableIdes.join(', ')}`,
    )
  }

  const installedFolders: string[] = []

  // Create .aiwcli container folder for method-specific files
  const resolver = new IdePathResolver(targetDir)
  const containerDir = resolver.getAiwcliContainer()
  await fs.mkdir(containerDir, {recursive: true})

  // Install non-dot folders into .aiwcli/ container (always overwrite)
  const nonDotInstalls = nonDotFolders.map(async (folder) => {
    const srcPath = join(templatePath, folder)
    const destPath = join(containerDir, folder)
    await copyDir(srcPath, destPath)
    return folder
  })

  const nonDotResults = await Promise.all(nonDotInstalls)
  installedFolders.push(...nonDotResults)

  // Install root-level _shared directory (shared across all templates)
  // Exclude IDE config folders (.claude, .windsurf) - they are used for settings merging only
  const templatesRoot = dirname(templatePath)
  const rootSharedSrc = join(templatesRoot, '_shared')
  const rootSharedDest = join(containerDir, '_shared')

  if (await pathExists(rootSharedSrc)) {
    await copyDir(rootSharedSrc, rootSharedDest, true) // excludeIdeFolders = true
    installedFolders.push('_shared')

    // Copy shared IDE content (e.g., _shared/.claude/commands/handoff.md)
    // These are non-method-owned files that live in IDE folders
    const sharedIdeInstalls = ides.map(async (ide) => {
      const sharedIdeFolder = join(rootSharedSrc, `.${ide}`)
      if (await pathExists(sharedIdeFolder)) {
        const destIdeFolder = resolver.getIdeDir(ide)
        await fs.mkdir(destIdeFolder, {recursive: true})
        // Merge shared IDE content, skipping files that already exist
        await mergeDirectory(sharedIdeFolder, destIdeFolder)
      }
    })
    await Promise.all(sharedIdeInstalls)
  }

  // Install method-owned IDE content (decomposed approach)
  // Instead of copying entire .claude/ from template, only copy method-namespaced subdirectories
  const ideInstalls = ides.map(async (ide) => {
    const folderName = dotFolders.get(ide)
    if (!folderName) return null

    const srcIdePath = join(templatePath, folderName)
    const destIdePath = resolver.getIdeDir(ide)
    await fs.mkdir(destIdePath, {recursive: true})

    // Scan the template IDE folder for subdirectories and copy method-owned content
    const ideEntries = await fs.readdir(srcIdePath, {withFileTypes: true})
    const subdirOps = ideEntries
      .filter((entry) => entry.isDirectory())
      .map(async (entry) => {
        const subdirSrc = join(srcIdePath, entry.name)
        const subdirDest = join(destIdePath, entry.name)

        // Check for method-namespaced child within this subdirectory
        const methodChildSrc = join(subdirSrc, templateName)
        if (await pathExists(methodChildSrc)) {
          // Copy only the method-namespaced subdirectory (overwrite)
          const methodChildDest = join(subdirDest, templateName)
          await copyDir(methodChildSrc, methodChildDest)
        } else {
          // No method-namespaced child — copy the entire subdirectory, merging with existing
          await mergeDirectory(subdirSrc, subdirDest)
        }
      })
    await Promise.all(subdirOps)

    return folderName
  })

  const ideResults = (await Promise.all(ideInstalls)).filter(
    (result): result is string => result !== null,
  )
  installedFolders.push(...ideResults)

  // Settings reconstruction is handled by the caller via reconstructIdeSettings()

  // Write resolved CLI binary path so template scripts can shell out to `aiw`
  await writeAiwBinPath(containerDir)

  return {
    installedFolders,
    sharedSettingsMerged: false,
    templatePath,
  }
}

/**
 * Write the resolved `aiw` binary path to `.aiwcli/.aiw-bin-path`.
 * Template scripts read this file to find the CLI binary for `aiw launch`.
 */
async function writeAiwBinPath(containerDir: string): Promise<void> {
  try {
    // process.argv[1] is the main script entry point (e.g., /path/to/aiw/bin/run.js)
    // Resolve to the bin directory to find the actual `aiw` executable
    const {execSync} = await import('node:child_process')
    const cmd = process.platform === 'win32' ? 'where aiw' : 'which aiw'
    const resolved = execSync(cmd, {encoding: 'utf-8', timeout: 3000, stdio: ['pipe', 'pipe', 'pipe']})
      .trim()
      .split(/\r?\n/)[0]
      ?.trim()

    if (resolved) {
      await fs.writeFile(join(containerDir, '.aiw-bin-path'), resolved, 'utf-8')
    }
  } catch {
    // Best-effort — aiw will still be found on PATH at runtime
  }
}

import * as os from 'node:os'
import * as path from 'node:path'

/** Fixed tmux server socket. Multiple named sessions share one server. */
export const TMUX_SOCKET_PATH = path.join(os.tmpdir(), 'aiwcli-tmux.sock')

/** Convert Windows path to MSYS2 POSIX path for tmux args. C:\foo\bar → /c/foo/bar */
export function toMsysPosixPath(winPath: string): string {
  if (process.platform !== 'win32') return winPath
  const normalized = winPath.replaceAll('\\', '/')
  const match = normalized.match(/^([A-Za-z]):\/(.*)/u)
  if (!match) return normalized
  return `/${match[1]!.toLowerCase()}/${match[2]!}`
}

/** Shell-safe single-quote escaping for bash command strings. */
export function quoteForSh(input: string): string {
  return `'${input.replaceAll("'", "'\"'\"'")}'`
}

import {type ChildProcess, execFileSync, execSync, spawn} from 'node:child_process'
import {writeFileSync} from 'node:fs'
import * as os from 'node:os'
import * as path from 'node:path'

import {resolveExecutable} from './runtime/executable-policy.js'
import {
  isNonWindowsPlatform,
  isWindowsPlatform,
  resolveTmuxColorModeForPlatform,
} from './runtime/platform-adapter.js'
import {isNativeTmuxAvailable, preflightWindowsTmux} from './runtime/tmux-preflight.js'
import {quoteForSh, TMUX_SOCKET_PATH, toMsysPosixPath} from './tmux-primitives.js'

export interface TmuxSessionOptions {
  /** Prepend tmux mouse enable command (default true). */
  enableMouse?: boolean
  /** Platform override for deterministic tests. */
  platform?: NodeJS.Platform | undefined
  /** Optional prompt text to deliver as a positional arg via temp file. */
  promptText?: string | undefined
  reattach?: boolean
  sessionName: string
  /** CLI args (e.g. ['--dangerously-skip-permissions']). */
  toolArgs: string[]
  /** Absolute path to tool binary (or bare command name on Unix). */
  toolPath: string
}

export interface TmuxSessionResult {
  exitCode: number
  reason?: string
  usedTmux: boolean
}

export type TmuxColorMode = 'c256' | 'truecolor'

function windowsTerminalOverrides(colorMode: TmuxColorMode): string {
  const stabilityOverrides = '*:kmous@,*:Ss@,*:Se@,*:Cs@,*:Cr@'
  if (colorMode === 'truecolor') {
    return `,xterm*:Tc,alacritty:Tc,${stabilityOverrides}`
  }

  return `,${stabilityOverrides}`
}

export function buildTmuxRuntimeBootstrapCommands(
  platform: NodeJS.Platform = process.platform,
  enableMouse = true,
): string[] {
  const colorMode = resolveTmuxColorMode(platform)
  const commands: string[] = []

  if (enableMouse) {
    commands.push('tmux set-option -g mouse on >/dev/null 2>&1 || true')
  }

  // Increase scrollback buffer from default 2000
  commands.push('tmux set-option -g history-limit 50000 >/dev/null 2>&1 || true')
  if (isWindowsPlatform(platform)) {
    commands.push('tmux set-option -g focus-events off >/dev/null 2>&1 || true')
  }

  // Configure terminal overrides for the active color mode.
  // Note: default-terminal is set before session creation.
  if (isWindowsPlatform(platform)) {
    commands.push(`tmux set -a terminal-overrides "${windowsTerminalOverrides(colorMode)}" >/dev/null 2>&1 || true`)
  } else {
    commands.push('tmux set -a terminal-overrides ",xterm*:Tc,alacritty:Tc" >/dev/null 2>&1 || true')
  }

  return commands
}

/** Color mode policy for tmux-launched sessions. */
export function resolveTmuxColorMode(platform: NodeJS.Platform = process.platform): TmuxColorMode {
  return resolveTmuxColorModeForPlatform(platform)
}

/**
 * Resolve the absolute path to a tool binary (e.g. 'claude', 'codex').
 *  On Windows prefers .exe, then extensionless, then .cmd.
 *  Returns null when the tool is not on PATH.
 */
export function findToolPath(name: string): null | string {
  return resolveExecutable(name, {windowsProfile: 'exeThenExtensionlessThenCmd'})
}

/** Spawn a process and return a promise that resolves when it exits. */
function spawnAttached(command: string, args: string[], env?: NodeJS.ProcessEnv): Promise<TmuxSessionResult> {
  return new Promise((resolve) => {
    let child: ChildProcess
    try {
      child = spawn(command, args, {stdio: 'inherit', env: env ?? process.env})
    } catch (error) {
      resolve({exitCode: -1, usedTmux: false, reason: error instanceof Error ? error.message : String(error)})
      return
    }

    child.on('error', (error) => {
      resolve({exitCode: -1, usedTmux: false, reason: error.message})
    })

    child.on('close', (code) => {
      if (code === 0) {
        resolve({exitCode: 0, usedTmux: true})
      } else {
        resolve({exitCode: code ?? 1, usedTmux: false, reason: `tmux exited with code ${code ?? 1}`})
      }
    })
  })
}

/** Build the shell command string from structured options. */
export function buildShellCommand(opts: TmuxSessionOptions): string {
  const {toolPath, toolArgs, promptText, enableMouse = true, platform = process.platform} = opts
  const colorMode = resolveTmuxColorMode(platform)
  const parts = buildTmuxRuntimeBootstrapCommands(platform, enableMouse)

  const cmdParts: string[] = []

  // On Windows, convert tool path to POSIX for MSYS2 bash
  const effectivePath = isWindowsPlatform(platform)
    ? toMsysPosixPath(toolPath)
    : toolPath
  cmdParts.push(quoteForSh(effectivePath))

  for (const arg of toolArgs) {
    cmdParts.push(quoteForSh(arg))
  }

  // Deliver prompt via temp file — avoids nested bash→tmux→sh quoting
  if (promptText) {
    const tmpFile = path.join(os.tmpdir(), `aiwcli-prompt-${Date.now()}-${process.pid}.txt`)
    writeFileSync(tmpFile, promptText, {encoding: 'utf-8', mode: 0o600})
    const posixTmpFile = isWindowsPlatform(platform) ? toMsysPosixPath(tmpFile) : tmpFile
    const bootstrap = `Read startup instructions from this file path before taking action: ${posixTmpFile}. Use that file as the initial context.`
    cmdParts.push(quoteForSh(bootstrap))
  }

  // Export COLORTERM only when truecolor is intentionally enabled.
  if (colorMode === 'truecolor') {
    parts.push('export COLORTERM=truecolor')
  } else {
    parts.push('unset COLORTERM')
  }

  // On Windows, use winpty to bridge MSYS2 pty (tmux) to ConPTY (native Windows TUI).
  // winpty cannot execute shell scripts (npm shims like 'codex', 'claude' are #!/bin/sh
  // wrappers). Wrap in `bash -c` so winpty launches bash.exe (a real binary), which
  // then runs the shell script that execs into node.exe.
  if (isWindowsPlatform(platform)) {
    const innerCmd = cmdParts.join(' ')
    parts.push(`exec winpty bash -c ${quoteForSh(innerCmd)}`)
  } else {
    parts.push(`exec ${cmdParts.join(' ')}`)
  }

  return parts.join('; ')
}

/**
 * Return env with Claude Code nesting-detection vars removed.
 *  Without this, Claude Code refuses to start inside tmux ("cannot launch
 *  claude within claude") because it inherits CLAUDECODE from the parent.
 *  Mirrors cleanTerminalEnv() in terminal.ts.
 */
function cleanTmuxEnv(extra?: Record<string, string>): NodeJS.ProcessEnv {
  const env = {...process.env, ...extra}
  delete env['CLAUDECODE']
  delete env['CLAUDE_CODE_ENTRYPOINT']
  return env
}

/**
 * Launch an interactive tmux session. Works on Unix (native tmux) and
 * Windows (Git Bash tmux). Never throws — all failures return `{usedTmux: false}`.
 */
export async function launchInTmuxSession(options: TmuxSessionOptions): Promise<TmuxSessionResult> {
  const {sessionName, reattach} = options
  const shellCommand = buildShellCommand(options)

  // Strategy 1: Native tmux on PATH (Unix only — on Windows, MSYS2 tmux.exe
  // appears on PATH but can't run outside a bash/MSYS2 environment)
  if (isNonWindowsPlatform() && isNativeTmuxAvailable()) {
    // Set default-terminal BEFORE creating the session so the first pane inherits
    // the correct TERM. Setting it inside buildShellCommand() is too late — TERM is
    // assigned at pane creation time, so the pane would get tmux's compile-time default.
    try {
      execSync('tmux start-server', {stdio: 'ignore', timeout: 3000})
      try {
        execSync('tmux set -g default-terminal "tmux-256color"', {stdio: 'ignore', timeout: 3000})
      } catch {
        execSync('tmux set -g default-terminal "screen-256color"', {stdio: 'ignore', timeout: 3000})
      }
    } catch { /* best-effort — session creation will still work */ }

    const args = ['new-session']
    if (reattach) args.push('-A')
    args.push('-c', process.cwd(), '-s', sessionName, shellCommand)
    return spawnAttached('tmux', args, cleanTmuxEnv())
  }

  // Strategy 2: Git Bash tmux (Windows)
  if (isWindowsPlatform()) {
    const preflight = preflightWindowsTmux()
    if (!preflight.available || !preflight.bashPath) {
      return {exitCode: -1, usedTmux: false, reason: preflight.reason ?? 'Windows tmux preflight failed'}
    }

    const {bashPath} = preflight

    // Set default-terminal BEFORE creating the session so the first pane inherits
    // the correct TERM (assigned at pane creation time, not after).
    const posixSocket = toMsysPosixPath(TMUX_SOCKET_PATH)
    try {
      execFileSync(bashPath, ['-lc', `tmux -S ${quoteForSh(posixSocket)} start-server`], {
        stdio: 'ignore', timeout: 3000,
        env: {...process.env, MSYS_NO_PATHCONV: '1'}, windowsHide: true,
      })
      try {
        execFileSync(bashPath, ['-lc', `tmux -S ${quoteForSh(posixSocket)} set -g default-terminal 'tmux-256color'`], {
          stdio: 'ignore', timeout: 3000,
          env: {...process.env, MSYS_NO_PATHCONV: '1'}, windowsHide: true,
        })
      } catch {
        try {
          execFileSync(bashPath, ['-lc', `tmux -S ${quoteForSh(posixSocket)} set -g default-terminal 'screen-256color'`], {
            stdio: 'ignore', timeout: 3000,
            env: {...process.env, MSYS_NO_PATHCONV: '1'}, windowsHide: true,
          })
        } catch { /* best-effort */ }
      }
    } catch { /* best-effort — session creation will still work */ }

    // ANTI-PATTERN: Do not use bash positional params ($1, $2, $3) to pass shell
    // commands to tmux on MSYS2. Quoting does not survive the bash→exec→tmux→sh
    // chain. Instead, build a single bash string with per-arg quoteForSh().
    const posixCwd = toMsysPosixPath(process.cwd())
    const tmuxArgs = ['-S', posixSocket, 'new-session']
    if (reattach) tmuxArgs.push('-A')
    tmuxArgs.push('-c', posixCwd, '-s', sessionName, shellCommand)
    const tmuxCmd = `exec tmux ${tmuxArgs.map(quoteForSh).join(' ')}`

    return spawnAttached(bashPath, ['-lc', tmuxCmd], cleanTmuxEnv({MSYS_NO_PATHCONV: '1'}))
  }

  // No tmux available
  return {exitCode: -1, usedTmux: false, reason: 'tmux not found'}
}

/** Best-effort enable tmux mouse support in the current session. */
export function enableTmuxMouse(): void {
  try {
    if (isNonWindowsPlatform()) {
      execSync('tmux set-option -g mouse on', {stdio: 'ignore', timeout: 3000})
      execSync('tmux set-option -g history-limit 50000', {stdio: 'ignore', timeout: 3000})
      return
    }

    const preflight = preflightWindowsTmux()
    const {bashPath} = preflight
    if (!preflight.available || !bashPath) return

    const winOpts = {
      stdio: 'ignore' as const,
      timeout: 3000,
      env: {...process.env, MSYS_NO_PATHCONV: '1'},
      windowsHide: true,
    }
    // When already inside tmux, target the active server via TMUX env.
    // Fallback to AIW's fixed socket when no active session is present.
    const tmuxPrefix = process.env.TMUX
      ? 'tmux'
      : `tmux -S ${quoteForSh(toMsysPosixPath(TMUX_SOCKET_PATH))}`

    execFileSync(bashPath, ['-lc', `${tmuxPrefix} set-option -g mouse on`], winOpts)
    execFileSync(bashPath, ['-lc', `${tmuxPrefix} set-option -g history-limit 50000`], winOpts)
    execFileSync(bashPath, ['-lc', `${tmuxPrefix} set-option -g focus-events off`], winOpts)

    // Strip 'kmous' so tmux handles mouse internally instead of forwarding to winpty
    // (winpty mangles wheel events into arrow keys). See buildShellCommand() for details.
    const setCommand = process.env.TMUX ? 'set -a' : 'set -ga'
    execFileSync(
      bashPath,
      ['-lc', `${tmuxPrefix} ${setCommand} terminal-overrides '${windowsTerminalOverrides('c256')}'`],
      winOpts,
    )
  } catch {
    // Best-effort — ignore failures
  }
}

/**
 * Best-effort enable 256-color and truecolor support in the current tmux session.
 *  Uses session-scoped settings (no -g) to avoid affecting other sessions.
 */
export function enableTmuxColors(): void {
  const colorMode = resolveTmuxColorMode()
  const baseOpts = {stdio: 'ignore' as const, timeout: 3000}
  try {
    if (isNonWindowsPlatform()) {
      try {
        execSync('tmux set default-terminal "tmux-256color"', baseOpts)
      } catch {
        execSync('tmux set default-terminal "screen-256color"', baseOpts)
      }

      execSync('tmux set -a terminal-overrides ",xterm*:Tc,alacritty:Tc"', baseOpts)
      return
    }

    const preflight = preflightWindowsTmux()
    const {bashPath} = preflight
    if (!preflight.available || !bashPath) return

    const winOpts = {
      ...baseOpts,
      env: {...process.env, MSYS_NO_PATHCONV: '1'},
      windowsHide: true,
    }
    // When already inside tmux, target the active server via TMUX env.
    // Fallback to AIW's fixed socket when no active session is present.
    const tmuxPrefix = process.env.TMUX
      ? 'tmux'
      : `tmux -S ${quoteForSh(toMsysPosixPath(TMUX_SOCKET_PATH))}`

    try {
      execFileSync(bashPath, ['-lc', `${tmuxPrefix} set default-terminal 'tmux-256color'`], winOpts)
    } catch {
      try {
        execFileSync(bashPath, ['-lc', `${tmuxPrefix} set default-terminal 'screen-256color'`], winOpts)
      } catch { /* best-effort */ }
    }

    // Separate try/catch so terminal-overrides failure doesn't suppress default-terminal success
    try {
      const override = windowsTerminalOverrides(colorMode)
      const setCommand = process.env.TMUX ? 'set -a' : 'set -ga'
      execFileSync(bashPath, ['-lc', `${tmuxPrefix} ${setCommand} terminal-overrides '${override}'`], winOpts)
    } catch { /* best-effort */ }
  } catch {
    // Best-effort — ignore failures
  }
}

