    it('should define --all flag that depends on --delete', () => {
      expect(BranchCommand.flags).to.have.property('all')
      expect(BranchCommand.flags.all).to.have.property('char', 'a')
      expect(BranchCommand.flags.all).to.have.property('dependsOn')
      expect(BranchCommand.flags.all.dependsOn).to.include('delete')
    })

    it('should define branchName argument as optional', () => {
      expect(BranchCommand.args).to.have.property('branchName')
      expect(BranchCommand.args.branchName).to.have.property('required', false)
    })
  })

  describe('flag validation (in-process)', () => {
    it('should error when no flag is provided', async () => {
      const {error} = await runCommand('branch')
      expect(error).to.exist
      expect(error!.message).to.match(/--main|--launch|--delete.*required/i)
    })

    it('should show help output when requested', async () => {
      const {error} = await runCommand('branch --help')
      // oclif help can short-circuit via an EEXIT(0) error in-process.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      expect((error as any)?.oclif?.exit ?? 0).to.equal(0)
    })

    it('should error when --launch provided without branch name', async () => {
      const {error} = await runCommand('branch --launch')
      expect(error).to.exist
      expect(error!.message).to.match(/branch name.*required/i)
    })

    it('should reject invalid branch names with spaces for --launch', async () => {
      const {error} = await runCommand(['branch', '--launch', 'branch with spaces'])
      expect(error).to.exist
      expect(error!.message).to.match(/invalid characters/i)
    })

    it('should exit with code 2 for invalid usage (no flags)', async () => {
      const {error} = await runCommand('branch')
      expect(error).to.exist
      // oclif sets exitCode on errors
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      expect((error as any).oclif?.exit).to.equal(2)
    })
  })

  describe('--delete flag behavior', () => {
    let testDir: string

    beforeEach(async () => {      testDir = await createTestGitRepo()
    })

    afterEach(async () => {
      await cleanupTestDir(testDir)
    })

    it('should error when branch name is not provided', () => {
      const absoluteBin = getAbsoluteBinPath()
      try {
        execSync(`node "${absoluteBin}" branch --delete`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        expect(err.stderr).to.match(/branch name.*required/i)
      }
    })

    it('should prevent deletion of main branch', () => {
      const absoluteBin = getAbsoluteBinPath()
      try {
        execSync(`node "${absoluteBin}" branch --delete main`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        expect(err.stderr).to.match(/cannot delete.*main|main.*protected/i)
      }
    })

    it('should prevent deletion of master branch', () => {
      const absoluteBin = getAbsoluteBinPath()
      try {
        execSync(`node "${absoluteBin}" branch --delete master`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        expect(err.stderr).to.match(/cannot delete.*master|master.*protected/i)
      }
    })

    it('should error when branch does not exist', () => {
      const absoluteBin = getAbsoluteBinPath()
      try {
        execSync(`node "${absoluteBin}" branch --delete nonexistent-branch`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        const normalizedError = err.stderr.replaceAll(/[^a-zA-Z0-9\s]/g, ' ').replaceAll(/\s+/g, ' ')
        expect(normalizedError).to.match(/does not exist|not found|no such branch/i)
      }
    })

    it('should error when trying to delete current branch', async () => {
      execSync('git checkout -b feature-branch', {cwd: testDir, stdio: 'ignore'})
      const absoluteBin = getAbsoluteBinPath()

      try {
        execSync(`node "${absoluteBin}" branch --delete feature-branch`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        expect(err.stderr).to.match(/currently on it/i)
      }
    })

    it('should delete a branch when not on it', async () => {      const absoluteBin = getAbsoluteBinPath()

      execSync('git checkout -b feature-to-delete', {cwd: testDir, stdio: 'ignore'})
      await fs.writeFile(join(testDir, 'feature.txt'), 'feature\n')
      execSync('git add .', {cwd: testDir, stdio: 'ignore'})
      execSync('git commit -m "Feature commit"', {cwd: testDir, stdio: 'ignore'})

      try {
        execSync('git checkout main', {cwd: testDir, stdio: 'ignore'})
      } catch {
        execSync('git checkout master', {cwd: testDir, stdio: 'ignore'})
      }

      const result = execSync(`node "${absoluteBin}" branch --delete feature-to-delete`, {
        cwd: testDir,
        encoding: 'utf8',
      })

      expect(result).to.match(/deleted/i)

      const branches = execSync('git branch', {cwd: testDir, encoding: 'utf8'})
      expect(branches).to.not.include('feature-to-delete')
    })
  })

  describe('--main flag behavior', () => {
    let testDir: string

    beforeEach(async () => {      testDir = await createTestGitRepo()
    })

    afterEach(async () => {
      await cleanupTestDir(testDir)
    })

    it('should error when already on main branch', async () => {      const absoluteBin = getAbsoluteBinPath()

      try {
        execSync('git checkout -b main', {cwd: testDir, stdio: 'ignore'})
      } catch {
        try {
          execSync('git checkout main', {cwd: testDir, stdio: 'ignore'})
        } catch {
          // Already on main or using master
        }
      }

      try {
        execSync(`node "${absoluteBin}" branch --main`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {stderr: string}
        expect(err.stderr).to.match(/already on|neither.*exists|worktree/i)
      }
    })
  })

  describe('--delete --all flag behavior', () => {
    let testDir: string

    beforeEach(async () => {      testDir = await createTestGitRepo()
    })

    afterEach(async () => {
      await cleanupTestDir(testDir)
    })

    it('should complete without error when there are no worktrees to delete', () => {      const absoluteBin = getAbsoluteBinPath()

      const result = execSync(`node "${absoluteBin}" branch --delete --all`, {
        cwd: testDir,
        encoding: 'utf8',
      })

      expect(result).to.match(/cleanup complete/i)
    })

    it('should preserve main/master branch (protected)', () => {      const absoluteBin = getAbsoluteBinPath()

      const result = execSync(`node "${absoluteBin}" branch --delete --all`, {
        cwd: testDir,
        encoding: 'utf8',
      })

      expect(result).to.match(/preserved/i)
    })
  })

  describe('exit codes (subprocess)', () => {
    it('should exit with non-zero code for environment error (not a git repo)', async () => {
      const nonGitDir = join(tmpdir(), `aiw-non-git-test-${randomUUID()}`)
      await fs.mkdir(nonGitDir, {recursive: true})
      const absoluteBin = getAbsoluteBinPath()

      try {
        execSync(`node "${absoluteBin}" branch --delete some-branch`, {
          cwd: nonGitDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {status: number; stderr: string}
        expect(err.status).to.be.greaterThan(0)
        expect(err.stderr).to.match(/not a git repository/i)
      } finally {
        await cleanupTestDir(nonGitDir)
      }
    })

    it('should exit with non-zero code for invalid usage (protected branch)', async () => {
      const testDir = await createTestGitRepo()
      const absoluteBin = getAbsoluteBinPath()

      try {
        execSync(`node "${absoluteBin}" branch --delete main`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown')
      } catch (error) {
        const err = error as {status: number; stderr: string}
        expect(err.status).to.be.greaterThan(0)
        expect(err.stderr).to.match(/cannot delete.*main|main.*protected/i)
      } finally {
        await cleanupTestDir(testDir)
      }
    })
  })

  describe('git repository requirement', () => {
    const flagsRequiringGitRepo = [
      {flag: '--delete some-branch', name: '--delete'},
      {flag: '--launch new-feature', name: '--launch'},
      {flag: '--main', name: '--main'},
      {flag: '--delete --all', name: '--delete --all'},
    ]

    for (const {flag, name} of flagsRequiringGitRepo) {
      it(`should error when not in a git repository (${name})`, async () => {
        const nonGitDir = join(tmpdir(), `aiw-non-git-test-${randomUUID()}`)
        await fs.mkdir(nonGitDir, {recursive: true})
        const absoluteBin = getAbsoluteBinPath()

        try {
          execSync(`node "${absoluteBin}" branch ${flag}`, {
            cwd: nonGitDir,
            encoding: 'utf8',
            stdio: ['pipe', 'pipe', 'pipe'],
          })
          expect.fail('Should have thrown')
        } catch (error) {
          const err = error as {stderr: string}
          expect(err.stderr).to.match(/not a git repository/i)
        } finally {
          await cleanupTestDir(nonGitDir)
        }
      })
    }
  })

  describe('branch name validation', () => {
    const validPattern = /^[a-zA-Z0-9._/-]+$/

    it('should accept valid branch names', () => {
      const validNames = [
        'feature-v1.0', 'release.1.2.3', 'fix.bug',
        'feature-branch', 'my-new-feature', 'bug-fix-123',
        'feature_branch', 'my_new_feature', 'bug_fix_123',
        'feature/my-branch', 'bugfix/issue-123', 'release/v1.0',
      ]
      for (const name of validNames) {
        expect(validPattern.test(name), `Expected "${name}" to be valid`).to.be.true
      }
    })

    it('should reject invalid branch names', () => {
      const invalidNames = [
        'my branch', 'feature branch', 'bug fix',
        'branch@name', 'feature#123', 'bug$fix', 'test!branch',
      ]
      for (const name of invalidNames) {
        expect(validPattern.test(name), `Expected "${name}" to be invalid`).to.be.false
      }
    })
  })
})

/**
 * @file Unit tests for clean command.
 *
 * Tests command structure, metadata, and output folder cleaning behavior.
 * Uses real temporary directories to test actual behavior rather than
 * checking source code strings.
 */

import {execSync} from 'node:child_process'
import {promises as fs} from 'node:fs'
import {join} from 'node:path'

import {expect} from 'chai'

import CleanCommand from '../../src/commands/clean.js'
import {cleanupTestDir, createTestDir, getAbsoluteBinPath} from '../helpers/test-utils.js'

describe('clean command', () => {
  const originalNodeEnv = process.env.NODE_ENV

  beforeAll(() => {
    process.env.NODE_ENV = 'production'
  })

  afterAll(() => {
    if (originalNodeEnv === undefined) {
      delete process.env.NODE_ENV
      return
    }

    process.env.NODE_ENV = originalNodeEnv
  })

  describe('command metadata', () => {
    it('should have static description field', () => {
      expect(CleanCommand.description).to.be.a('string')
      expect(CleanCommand.description.length).to.be.greaterThan(0)
    })

    it('should reference output folder in description', () => {
      expect(CleanCommand.description.toLowerCase()).to.include('output')
    })

    it('should reference method in description', () => {
      expect(CleanCommand.description.toLowerCase()).to.include('method')
    })

    it('should have static examples array', () => {
      expect(CleanCommand.examples).to.be.an('array')
      expect(CleanCommand.examples.length).to.be.greaterThan(0)
    })

    it('should include method flag example', () => {
      const {examples} = CleanCommand
      const hasMethodExample = examples.some((ex: string) => ex.includes('--method'))
      expect(hasMethodExample).to.be.true
    })

    it('should include -m shorthand example', () => {
      const {examples} = CleanCommand
      const hasShortExample = examples.some((ex: string) => ex.includes('-m '))
      expect(hasShortExample).to.be.true
    })

    it('should include dry-run example', () => {
      const {examples} = CleanCommand
      const hasDryRunExample = examples.some((ex: string) => ex.includes('--dry-run'))
      expect(hasDryRunExample).to.be.true
    })

    it('should include force example', () => {
      const {examples} = CleanCommand
      const hasForceExample = examples.some((ex: string) => ex.includes('--force'))
      expect(hasForceExample).to.be.true
    })

    it('should include --all example', () => {
      const {examples} = CleanCommand
      const hasAllExample = examples.some((ex: string) => ex.includes('--all'))
      expect(hasAllExample).to.be.true
    })

    it('should include -a shorthand example', () => {
      const {examples} = CleanCommand
      const hasShortExample = examples.some((ex: string) => ex.includes('-a '))
      expect(hasShortExample).to.be.true
    })
  })

  describe('command structure', () => {
    it('should have run method', () => {
      expect(CleanCommand.prototype.run).to.be.a('function')
    })

    it('should extend BaseCommand', () => {
      expect(CleanCommand).to.have.property('baseFlags')
    })

    it('should have method flag', () => {
      expect(CleanCommand.flags).to.have.property('method')
      expect(CleanCommand.flags['method']).to.have.property('char', 'm')
    })

    it('should have all flag', () => {
      expect(CleanCommand.flags).to.have.property('all')
      expect(CleanCommand.flags['all']).to.have.property('char', 'a')
    })

    it('should have method and all flags as mutually exclusive', () => {
      expect(CleanCommand.flags['method']).to.have.property('exclusive').that.includes('all')
      expect(CleanCommand.flags['all']).to.have.property('exclusive').that.includes('method')
    })

    it('should have dry-run flag', () => {
      expect(CleanCommand.flags).to.have.property('dry-run')
      expect(CleanCommand.flags['dry-run']).to.have.property('char', 'n')
    })

    it('should have force flag', () => {
      expect(CleanCommand.flags).to.have.property('force')
      expect(CleanCommand.flags['force']).to.have.property('char', 'f')
    })
  })

  describe('behavioral tests', () => {
    let testDir: string
    const binPath = getAbsoluteBinPath()

    beforeEach(async () => {
      testDir = await createTestDir()
    })

    afterEach(async () => {
      await cleanupTestDir(testDir)
    })

    it('should construct output folder path as _method-output', async () => {
      // Create output folder with expected naming pattern
      const outputFolder = join(testDir, '_bmad-output')
      await fs.mkdir(outputFolder)
      await fs.writeFile(join(outputFolder, 'test.txt'), 'content')

      // Run with dry-run to verify folder is found
      const result = execSync(`node "${binPath}" clean --method bmad --dry-run`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      expect(result).to.include('_bmad-output')
      expect(result).to.include('test.txt')
    })

    it('should list folder contents in dry-run mode', async () => {
      const outputFolder = join(testDir, '_gsd-output')
      await fs.mkdir(outputFolder)
      await fs.writeFile(join(outputFolder, 'file1.md'), 'content1')
      await fs.writeFile(join(outputFolder, 'file2.md'), 'content2')
      const subDir = join(outputFolder, 'subdir')
      await fs.mkdir(subDir)

      const result = execSync(`node "${binPath}" clean --method gsd --dry-run`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      expect(result).to.include('file1.md')
      expect(result).to.include('file2.md')
      expect(result).to.include('subdir')
      expect(result).to.include('3 item(s)')
    })

    it('should delete folder contents with --force flag', async () => {
      const outputFolder = join(testDir, '_test-output')
      await fs.mkdir(outputFolder)
      await fs.writeFile(join(outputFolder, 'delete-me.txt'), 'to be deleted')

      // Verify file exists before
      const beforeStat = await fs.stat(join(outputFolder, 'delete-me.txt'))
      expect(beforeStat.isFile()).to.be.true

      // Run with force to skip confirmation
      execSync(`node "${binPath}" clean --method test --force`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      // Verify file is deleted
      const entries = await fs.readdir(outputFolder)
      expect(entries).to.have.length(0)
    })

    it('should report error when neither --method nor --all is provided', () => {
      try {
        execSync(`node "${binPath}" clean`, {
          cwd: testDir,
          encoding: 'utf8',
          stdio: ['pipe', 'pipe', 'pipe'],
        })
        expect.fail('Should have thrown an error')
      } catch (error) {
        const err = error as {status: number; stderr: string;}
        expect(err.stderr).to.include('Either --method or --all is required')
        expect(err.status).to.be.greaterThan(0)
      }
    })

    it('should report when output folder does not exist', () => {
      const result = execSync(`node "${binPath}" clean --method nonexistent --dry-run`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      expect(result).to.include('does not exist')
    })

    it('should find all output folders with --all flag', async () => {
      // Create multiple output folders
      await fs.mkdir(join(testDir, '_bmad-output'))
      await fs.writeFile(join(testDir, '_bmad-output', 'file1.txt'), 'content')
      await fs.mkdir(join(testDir, '_gsd-output'))
      await fs.writeFile(join(testDir, '_gsd-output', 'file2.txt'), 'content')
      // Create a non-output folder (should be ignored)
      await fs.mkdir(join(testDir, 'regular-folder'))
      await fs.writeFile(join(testDir, 'regular-folder', 'ignored.txt'), 'content')

      const result = execSync(`node "${binPath}" clean --all --dry-run`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      expect(result).to.include('_bmad-output')
      expect(result).to.include('_gsd-output')
      expect(result).to.not.include('regular-folder')
      expect(result).to.include('2 output folder(s)')
    })

    it('should report when all output folders are empty', async () => {
      // Create empty output folder
      await fs.mkdir(join(testDir, '_empty-output'))

      const result = execSync(`node "${binPath}" clean --method empty --dry-run`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      expect(result).to.include('already empty')
    })

    it('should recursively delete subdirectories', async () => {
      const outputFolder = join(testDir, '_nested-output')
      await fs.mkdir(outputFolder)
      const subDir = join(outputFolder, 'level1')
      await fs.mkdir(subDir)
      const deepDir = join(subDir, 'level2')
      await fs.mkdir(deepDir)
      await fs.writeFile(join(deepDir, 'deep-file.txt'), 'deep content')

      // Run with force
      execSync(`node "${binPath}" clean --method nested --force`, {
        cwd: testDir,
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
      })

      // Verify all contents deleted
      const entries = await fs.readdir(outputFolder)
      expect(entries).to.have.length(0)
    })
  })
})

import {mkdtempSync, rmSync} from 'node:fs'
import {tmpdir} from 'node:os'
import {join} from 'node:path'

import {expect} from 'chai'

import {
  bindSession,
  createContext,
  determineArtifactType,
  getContext,
  getContextBySessionId,
  updateMode,
} from '../../../src/lib/context/context-store.js'

describe('context-store', () => {
  let projectRoot: string

  beforeEach(() => {
    projectRoot = mkdtempSync(join(tmpdir(), 'aiwcli-context-'))
  })

  afterEach(() => {
    rmSync(projectRoot, {recursive: true, force: true})
  })

  it('creates and loads context state under a custom project root', () => {
    const context = createContext('ctx-test', 'Refactor context layer', 'cc-native', projectRoot, ['refactor'])
    const loaded = getContext(context.id, projectRoot)

    expect(loaded).to.not.equal(null)
    expect(loaded?.id).to.equal('ctx-test')
    expect(loaded?.summary).to.equal('Refactor context layer')
    expect(loaded?.mode).to.equal('idle')
  })

  it('binds session IDs and resolves context by session ID', () => {
    const context = createContext('ctx-session', 'Session binding', 'cc-native', projectRoot)
    const sessionId = 'session-123'

    const didBind = bindSession(context.id, sessionId, projectRoot)
    const resolved = getContextBySessionId(sessionId, projectRoot)

    expect(didBind).to.equal(true)
    expect(resolved?.id).to.equal(context.id)
    expect(resolved?.session_ids).to.include(sessionId)
  })

  it('uses explicit next_artifact_type when determining staged artifact type', () => {
    const context = createContext('ctx-artifact', 'Artifact type', 'cc-native', projectRoot)
    updateMode(context.id, 'has_staged_work', projectRoot, {plan_path: '/tmp/plan.md', plan_hash: 'abc'})
    const loaded = getContext(context.id, projectRoot)

    expect(loaded).to.not.equal(null)
    if (!loaded) return

    loaded.next_artifact_type = 'handoff'
    expect(determineArtifactType(loaded)).to.equal('handoff')
  })
})

import {existsSync, readdirSync, readFileSync} from 'node:fs'
import {dirname, join, resolve} from 'node:path'
import {fileURLToPath} from 'node:url'

import {expect} from 'chai'

function repoRoot(): string {
  const fromFile = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..')
  if (existsSync(join(fromFile, 'packages', 'cli', 'src', 'lib', 'runtime', 'subprocess-utils.ts'))) return fromFile

  const cwd = resolve(process.cwd())
  if (existsSync(join(cwd, 'packages', 'cli', 'src', 'lib', 'runtime', 'subprocess-utils.ts'))) return cwd

  throw new Error('Unable to resolve repo root for shared lib sync tests')
}

function read(pathParts: string[]): string {
  return readFileSync(join(repoRoot(), ...pathParts), 'utf8')
}

describe('shared lib sync', () => {
  const segments = ['runtime', 'context', 'hooks'] as const

  for (const segment of segments) {
    it(`keeps ${segment} files synced between canonical lib and template copy`, () => {
      const canonicalDir = join(repoRoot(), 'packages', 'cli', 'src', 'lib', segment)
      const templateDir = join(repoRoot(), 'packages', 'cli', 'src', 'templates', '_shared', 'lib-ts', segment)

      const files = readdirSync(canonicalDir).filter((name) => name.endsWith('.ts'))
      expect(files.length).to.be.greaterThan(0)

      for (const file of files) {
        const canonical = read(['packages', 'cli', 'src', 'lib', segment, file])
        const template = read(['packages', 'cli', 'src', 'templates', '_shared', 'lib-ts', segment, file])
        expect(template).to.equal(canonical)
      }
    })
  }

  it('keeps shared types synced between canonical lib and template copy', () => {
    const canonical = read(['packages', 'cli', 'src', 'lib', 'types.ts'])
    const template = read(['packages', 'cli', 'src', 'templates', '_shared', 'lib-ts', 'types.ts'])
    expect(template).to.equal(canonical)
  })
})

import {expect} from 'chai'
import sinon from 'sinon'

import {adaptHookCommand, validateCommandsForPlatform} from '../../src/lib/platform-commands.js'

describe('platform-commands', () => {
  describe('adaptHookCommand', () => {
    let platformStub: sinon.SinonStub

    afterEach(() => {
      platformStub?.restore()
    })

    it('is a no-op on non-Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('linux')
      const cmd = 'bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_shared/hooks-ts/session_start.ts'
      expect(adaptHookCommand(cmd)).to.equal(cmd)
    })

    it('expands ~ to absolute home path on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_shared/hooks-ts/session_start.ts'
      const result = adaptHookCommand(cmd)
      expect(result).to.not.include('~/')
      expect(result).to.include('.aiwcli/bin/resolve-run.ts')
      expect(result).to.include('.aiwcli/_shared/hooks-ts/session_start.ts')
      // Should be quoted for paths with spaces
      expect(result).to.match(/bun ".*\.aiwcli\/bin\/resolve-run\.ts"/)
    })

    it('strips bash env-var prefix on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'NO_COLOR= FORCE_COLOR=2 bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_shared/scripts/status_line.ts'
      const result = adaptHookCommand(cmd)
      expect(result).to.not.include('NO_COLOR=')
      expect(result).to.not.include('FORCE_COLOR=2')
      expect(result).to.match(/^bun "/)
    })

    it('preserves bash env-var prefix on Unix', () => {
      platformStub = sinon.stub(process, 'platform').value('darwin')
      const cmd = 'NO_COLOR= FORCE_COLOR=2 bun ~/.aiwcli/bin/resolve-run.ts .aiwcli/_shared/scripts/status_line.ts'
      expect(adaptHookCommand(cmd)).to.equal(cmd)
    })

    it('handles commands without resolver token on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const cmd = 'echo hello'
      expect(adaptHookCommand(cmd)).to.equal('echo hello')
    })
  })

  describe('validateCommandsForPlatform', () => {
    let platformStub: sinon.SinonStub

    afterEach(() => {
      platformStub?.restore()
    })

    it('is a no-op on Unix', () => {
      platformStub = sinon.stub(process, 'platform').value('linux')
      expect(() => validateCommandsForPlatform(['bun ~/.aiwcli/bin/resolve-run.ts foo'])).to.not.throw()
    })

    it('throws on unexpanded ~/ on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      expect(() => validateCommandsForPlatform(['bun ~/.aiwcli/bin/resolve-run.ts foo'])).to.throw(/unexpanded ~\//)
    })

    it('throws on bash env prefix on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      expect(() => validateCommandsForPlatform(['NO_COLOR= bun something'])).to.throw(/bash env prefix/)
    })

    it('passes for adapted commands on Windows', () => {
      platformStub = sinon.stub(process, 'platform').value('win32')
      const adapted = ['bun "C:/Users/test/.aiwcli/bin/resolve-run.ts" .aiwcli/foo.ts']
      expect(() => validateCommandsForPlatform(adapted)).to.not.throw()
    })
  })
})
